    "limits.title": "What the Kirby-Desai Scale Cannot Know",
    "limits.p1": "The Kirby-Desai scale provides a statistical reference range based on a 100-patient retrospective study. It is not an individual guarantee. Four clinical variables cannot be measured by a questionnaire:",
    "limits.item_immune_title": "1. Individual Immune & Lymphatic Phagocytosis",
    "limits.item_immune_desc": "Lasers shatter ink particles; your body's macrophages and lymphatic system actually clear the ink. Individual macrophage activity and metabolic clearance speed vary widely.",
    "limits.item_chemistry_title": "2. Unregulated Ink Chemistry & Pigment Depth",
    "limits.item_chemistry_desc": "Tattoo inks are proprietary mixtures of pigments, binders and other ingredients, and the depth the needle reached varies. Both change how the ink responds to the laser.",
    "limits.item_smoking_title": "3. Smoking & Microcirculation",
    "limits.item_smoking_desc": "One study of 352 patients (Bencini et al., Arch Dermatol 2012) found that smokers were about 70% less likely than non-smokers to reach removal after 10 sessions. The authors suggest that cigarette smoke may affect the cells that clear the pigment.",
    "limits.item_paradox_title": "4. White Ink & Paradoxical Darkening",
