    "faq.title": "Frequently Asked Clinical Questions",
    "faq.subtitle": "Answers about how laser removal works, preparation and plateaus. Your clinic's advice comes first.",
    "faq.expand_all": "Expand All",
    "faq.collapse_all": "Collapse All",
    "faq.direct_link": "Direct link to this question",
    "faq.link_copied": "Direct link copied to clipboard",
    "faq.q1_title": "What happens if laser tattoo removal stops working or hits a fading plateau?",
    "faq.q1_body": "A fading plateau often occurs when the ink that breaks up easily has cleared, leaving deeper or more stubborn pigment behind. When fading stalls, your provider may change their approach for what remains, or leave longer gaps between sessions (often 12 weeks or more, a common clinic practice) to give the body more time to clear the fragments. What changes, if anything, is a decision your provider makes in person, not something this tool can specify.",
    "faq.q2_title": "How should I prepare my skin before a laser tattoo removal session?",
    "faq.q2_body": "Clinics commonly ask you to avoid sun exposure, tanning beds and self-tanners for several weeks before treatment (often 4 weeks or more; follow your clinic's own rule), because tanned skin competes with the ink for laser energy and raises the risk of pigment changes. Many also ask you to shave the area the day before, arrive with clean skin without cosmetics, moisturisers or deodorant, and use numbing cream only if they tell you to. Some ask you to avoid alcohol and aspirin beforehand. These are clinic practices: your provider's instructions come first.",
    "faq.q3_title": "Why do multi-colored inks (green, blue, yellow) require different lasers than black?",
    "faq.q3_body": "Laser tattoo removal works by a pigment absorbing light energy and fracturing into smaller pieces the body can clear; a given wavelength only works well if the target pigment actually absorbs it. Black ink absorbs a very broad range of light and generally responds most reliably. Red, blue, green, and purple pigments absorb more narrowly, and yellow is notoriously the hardest colour to clear because it absorbs light poorly across the range that is safe for skin. This is exactly why multi-colour work often needs more sessions than solid black. Which laser and wavelength your provider chooses for your specific ink is a clinical decision made in person, not something this tool can specify.",
    "faq.q4_title": "Can white ink or cosmetic tattoo pigment turn black when lasered?",
    "faq.q4_body": "Yes. This is called paradoxical darkening. White, flesh-tone and many cosmetic pigments contain titanium dioxide or iron oxide. The laser pulse can chemically change these pigments, so that white, pink or skin-tone ink turns grey or black, and that darkening can be hard to remove. This is why practitioners test a small spot on cosmetic or white ink before treating the whole area.",
    "faq.q5_title": "How much does smoking tobacco affect the number of sessions required?",
    "faq.q5_body": "One study of 352 patients in Milan (Bencini et al., Archives of Dermatology, 2012) found that smokers were about 70% less likely than non-smokers to reach removal after 10 sessions. The authors suggest that substances in cigarette smoke may affect the cells that clear the broken-up pigment. It is one study, and it measured the chance of success, not a number of extra sessions, so this tool does not add a smoking percentage to your estimate.",
    "faq.q6_title": "When is a tattoo faded enough for a cover-up instead of complete clearance?",
    "faq.q6_body": "Many tattoo artists look for roughly 50% to 70% fading before a cover-up, rather than full removal (industry practice). A cover-up usually needs fewer sessions than full removal, but no study gives a fixed number. Work with your tattoo artist: once dark outlines have faded to a soft grey, the artist can usually design over them without the old work showing through. Studio rule of thumb: wait at least 8 to 12 weeks after your last laser session, until the skin has fully healed, before tattooing.",
    "faq.q7_title": "How does my Fitzpatrick skin type influence laser safety and treatment speed?",
    "faq.q7_body": "Fitzpatrick skin types I to III have less epidermal melanin, which generally gives a provider more room to work without affecting the surrounding skin colour. Skin types IV to VI contain more natural melanin, which competes with the tattoo pigment for the laser's energy and raises the risk of the skin itself darkening or lightening (hyperpigmentation or hypopigmentation) if the approach is not adjusted for that skin type. A provider experienced with darker skin types will adjust their approach accordingly; this is exactly why the plan is set in person, not by a website.",
    "faq.q8_title": "Does laser tattoo removal hurt, and what pain management options are available?",
    "faq.q8_body": "Most clients compare the sensation of a laser pulse to the snap of a rubber band against the skin accompanied by intense heat. Because treatment areas are often sensitive, modern clinics use several pain mitigation strategies: continuous forced cold air chilling directed at the skin before, during, and after pulses; topical compounded numbing creams applied 30 to 60 minutes prior; and ice compression. In clinical settings, local infiltration may be offered for highly sensitive anatomical sites.",
    "faq.q9_title": "Why are sessions spaced weeks apart, and can treatments be scheduled sooner?",
    "faq.q9_body": "Rushing sessions does not speed up removal and raises the risk of skin damage. The laser breaks the ink into smaller fragments; your body then clears them over the following weeks. The Kirby-Desai paper assumed 6 to 8 weeks between sessions, and one large study (Bencini et al., 2012) linked intervals of 8 weeks or less to lower success, so many clinics now leave longer gaps. Your clinic sets the interval.",
