    "calendar.ics_completed_alert": "Toutes les séances prévues sont déjà enregistrées comme effectuées.",
    "limits.title": "Ce que l'échelle de Kirby-Desai ne peut pas prédire",
    "limits.p1": "L'échelle de Kirby-Desai fournit une fourchette statistique de référence issue d'une étude rétrospective sur 100 patients. Il ne s'agit pas d'une garantie individuelle. Quatre variables cliniques ne peuvent pas être mesurées par un questionnaire :",
    "limits.item_immune_title": "1. Phagocytose immunitaire et lymphatique individuelle",
    "limits.item_immune_desc": "Le laser fragmente les particules d'encre ; ce sont les macrophages et le système lymphatique de votre organisme qui éliminent réellement l'encre. L'activité macrophagique et la vitesse de clairance métabolique varient grandement d'une personne à l'autre.",
    "limits.item_chemistry_title": "2. Chimie des encres non réglementée et profondeur du pigment",
    "limits.item_chemistry_desc": "Les encres de tatouage sont des mélanges exclusifs de pigments, de liants et d'autres ingrédients, et la profondeur atteinte par l'aiguille varie. Ces deux facteurs modifient la réaction de l'encre au laser.",
    "limits.item_smoking_title": "3. Tabagisme et microcirculation",
    "limits.item_smoking_desc": "Une étude portant sur 352 patients (Bencini et al., Arch Dermatol 2012) a révélé que les fumeurs avaient environ 70 % de chances en moins que les non-fumeurs d'atteindre l'élimination après 10 séances. Les auteurs suggèrent que la fumée de cigarette pourrait affecter les cellules qui éliminent le pigment.",
    "limits.item_paradox_title": "4. Encre blanche et noircissement paradoxal",
    "limits.item_paradox_desc": "Les encres blanches, couleur chair et cosmétiques contenant du dioxyde de titane ou de l'oxyde de fer peuvent devenir grises ou noires lorsqu'elles sont traitées au laser (assombrissement paradoxal), et cet assombrissement peut être difficile à éliminer.",
    "questions.title": "Questions à poser à votre centre laser",
    "questions.subtitle": "Apportez cette liste de vérification imprimable lors de votre consultation initiale :",
    "questions.q1_title": "1. Test préliminaire (Spot test)",
    "questions.q1_body": "Allez-vous effectuer un point de test sur une zone discrète pour évaluer ma réaction cutanée et vérifier l'absence de noircissement paradoxal avant de traiter tout le tatouage ?",
    "questions.q2_title": "2. Espacement des séances et intervalles",
    "questions.q2_body": "Comment déterminez-vous l'espacement entre les séances ? Allongerez-vous l'intervalle à mesure que l'encre s'atténue pour donner au système immunitaire le temps de résorber les pigments fragmentés ?",
    "questions.q3_title": "3. Spécificités des pigments et protection de la mélanine",
    "questions.q3_body": "Quelles longueurs d'onde laser utiliserez-vous pour mes teintes d'encre spécifiques, et quelles précautions prenez-vous pour protéger ma mélanine naturelle de l'hypo ou de l'hyperpigmentation ?",
    "questions.q4_title": "4. Palier d'atténuation et ajustements de protocole",
    "questions.q4_body": "Quel est votre protocole clinique si le détatouage atteint un palier ou ralentit après plusieurs séances ?",
    "questions.q5_title": "5. Concertation avec le tatoueur (en cas de cover-up)",
    "questions.q5_body": "En cas d'éclaircissement pour un cover-up, accepterez-vous d'évaluer le tatouage avec mon tatoueur pour déterminer le stade où l'atténuation est suffisante pour encrer le nouveau projet ?",
