    "related.ink_title": "Décodeur d'ingrédients d'encre",
    "related.ink_desc": "Consultez les numéros de colorants CI, codes CAS et la conformité EU REACH des pigments de tatouage.",
    "legal.disclaimer": "Avis de référence clinique : Cet estimateur applique l'algorithme d'évaluation clinique de Kirby-Desai (Kirby W, Desai A, J Clin Aesthet Dermatol. 2009;2(3):32–37) à titre purement informatif et pédagogique. L'élimination réelle dépend de la phagocytose immunitaire individuelle, de la technologie laser employée (nanoseconde vs picoseconde), de la pratique du praticien, du diamètre de spot et de la composition chimique des encres. Cet outil ne constitue pas un avis médical et ne garantit aucun effacement complet. Consultez toujours un médecin lasériste ou un dermatologue qualifié en présentiel.",
