    "aftercare.title": "Liste de contrôle des soins post-intervention",
    "aftercare.subtitle": "Des soins minutieux réduisent le risque d'infection et de modifications pigmentaires. Les consignes de votre propre clinique sont prioritaires.",
    "aftercare.stage1_title": "Étape 1 : Phase aiguë (Heures 0 à 48)",
    "aftercare.stage1_item1": "Appliquez des compresses froides pendant 10 à 15 minutes à la fois pour réduire l'enflure.",
    "aftercare.stage1_item2": "Surélevez un bras ou une jambe traité au repos pour aider à réduire l'enflure.",
    "aftercare.stage1_item3": "Appliquez une fine couche de vaseline ou la pommade fournie par votre clinique ; ne percez pas et ne videz pas les cloques.",
    "aftercare.stage1_item4": "Évitez les douches chaudes, saunas, bains à remous et efforts intenses pendant 48 heures.",
    "aftercare.stage2_title": "Étape 2 : Récupération dermique (Jours 3 à 14)",
    "aftercare.stage2_item1": "Nettoyez délicatement une fois par jour avec un savon doux sans parfum ; séchez en tamponnant.",
    "aftercare.stage2_item2": "Ne grattez et n'arrachez jamais les croûtes ou la peau des cloques pour prévenir cicatrices et infections.",
    "aftercare.stage2_item3": "Portez des vêtements amples et respirants pour protéger la zone de tout frottement mécanique.",
    "aftercare.stage3_title": "Étape 3 : Protection solaire (Semaines 2 à 8+)",
    "aftercare.stage3_item1": "Utilisez un écran solaire à large spectre (FPS 30 ou plus) ou gardez la zone couverte pour réduire le risque de modifications pigmentaires.",
    "aftercare.stage3_item2": "Suivez toutes les instructions supplémentaires de votre clinique, par exemple concernant le moment où vous pouvez nager ou faire de l'exercice à nouveau.",
    "aftercare.stage3_item3": "Respectez l'intervalle complet recommandé par votre clinique avant la prochaine séance de laser.",
    "aftercare.progress_label": "Progression du protocole : {done} sur {total} validés",
