    "faq.title": "Questions cliniques fréquentes",
    "faq.subtitle": "Réponses sur le fonctionnement de l'élimination au laser, la préparation et les plateaux. Les conseils de votre clinique sont prioritaires.",
    "faq.expand_all": "Tout développer",
    "faq.collapse_all": "Tout réduire",
    "faq.direct_link": "Lien direct vers cette question",
    "faq.link_copied": "Lien direct copié dans le presse-papiers",
    "faq.q1_title": "Que se passe-t-il si le détatouage laser semble stagner ou atteint un plateau d'éclaircissement ?",
    "faq.q1_body": "Un plateau d'atténuation se produit souvent lorsque l'encre qui se fragmente facilement a disparu, laissant derrière elle un pigment plus profond ou plus tenace. Lorsque l'atténuation stagne, votre prestataire peut modifier son approche pour ce qui reste, ou espacer davantage les séances (souvent 12 semaines ou plus, une pratique courante en clinique) pour donner au corps plus de temps pour éliminer les fragments. Les changements éventuels sont décidés par votre prestataire en personne, et non par cet outil.",
    "faq.q2_title": "Comment préparer ma peau avant une séance de détatouage laser ?",
    "faq.q2_body": "Les cliniques vous demandent généralement d'éviter l'exposition au soleil, les lits de bronzage et les autobronzants pendant plusieurs semaines avant le traitement (souvent 4 semaines ou plus ; suivez les règles de votre propre clinique), car la peau bronzée concurrence l'encre pour l'énergie du laser et augmente le risque de modifications pigmentaires. Nombre d'entre elles vous demandent également de raser la zone la veille, de vous présenter avec une peau propre, sans produits cosmétiques, hydratants ou déodorant, et d'utiliser une crème anesthésiante uniquement sur leurs instructions. Certaines vous demandent d'éviter l'alcool et l'aspirine au préalable. Ce sont des pratiques de clinique : les instructions de votre praticien sont prioritaires.",
    "faq.q3_title": "Pourquoi les encres de couleur (vert, bleu, jaune) nécessitent-elles des lasers différents du noir ?",
    "faq.q3_body": "Le détatouage laser fonctionne parce qu'un pigment absorbe l'énergie lumineuse et se fragmente en particules que le corps peut éliminer ; une longueur d'onde donnée n'est efficace que si le pigment ciblé l'absorbe réellement. L'encre noire absorbe une très large partie du spectre lumineux et répond généralement le plus facilement. Les pigments rouge, bleu, vert et violet absorbent plus étroitement, et le jaune est notoirement le plus difficile à éliminer car il absorbe mal la lumière dans la fenêtre sûre pour la peau. C'est exactement pourquoi un tatouage multicolore demande souvent plus de séances qu'un tatouage noir uni. Le choix du laser et de la longueur d'onde pour vos couleurs précises relève d'une décision clinique prise en personne par votre praticien, non de cet outil.",
    "faq.q4_title": "L'encre blanche ou les pigments de maquillage permanent peuvent-ils noircir sous l'effet du laser ?",
    "faq.q4_body": "Oui. C'est ce qu'on appelle l'assombrissement paradoxal. Le blanc, les tons chair et de nombreux pigments cosmétiques contiennent du dioxyde de titane ou de l'oxyde de fer. L'impulsion laser peut modifier chimiquement ces pigments, de sorte que l'encre blanche, rose ou couleur chair devient grise ou noire, et cet assombrissement peut être difficile à éliminer. C'est pourquoi les praticiens testent une petite zone sur de l'encre cosmétique ou blanche avant de traiter toute la zone.",
    "faq.q5_title": "Dans quelle mesure le tabagisme influence-t-il le nombre de séances nécessaires ?",
    "faq.q5_body": "Une étude portant sur 352 patients à Milan (Bencini et al., Archives of Dermatology, 2012) a révélé que les fumeurs avaient environ 70 % de chances en moins que les non-fumeurs d'atteindre l'élimination après 10 séances. Les auteurs suggèrent que des substances présentes dans la fumée de cigarette peuvent affecter les cellules qui éliminent le pigment fragmenté. Il s'agit d'une seule étude, qui a mesuré la probabilité de succès et non un nombre de séances supplémentaires, de sorte que cet outil n'ajoute pas de pourcentage lié au tabagisme à votre estimation.",
    "faq.q6_title": "À quel stade un tatouage est-il suffisamment estompé pour un recouvrement ?",
    "faq.q6_body": "De nombreux tatoueurs recherchent environ 50 % à 70 % d'atténuation avant un cover-up, plutôt qu'une élimination complète (pratique de l'industrie). Un cover-up nécessite généralement moins de séances qu'une élimination complète, mais aucune étude ne donne de chiffre fixe. Travaillez avec votre tatoueur : une fois que les contours sombres se sont estompés en un gris doux, le tatoueur peut généralement dessiner par-dessus sans que l'ancien travail ne transparaisse. Règle empirique du studio : attendez au moins 8 à 12 semaines après votre dernière séance de laser, jusqu'à ce que la peau soit complètement guérie, avant de vous faire tatouer.",
    "faq.q7_title": "Comment mon phototype de Fitzpatrick influence-t-il la sécurité et la durée du détatouage ?",
    "faq.q7_body": "Les phototypes de Fitzpatrick I à III ont moins de mélanine épidermique, ce qui laisse généralement plus de marge au praticien sans affecter la couleur de la peau environnante. Les phototypes IV à VI contiennent davantage de mélanine naturelle, qui entre en compétition avec le pigment du tatouage pour l'énergie du laser et augmente le risque que la peau elle-même s'assombrisse ou s'éclaircisse (hyperpigmentation ou hypopigmentation) si l'approche n'est pas adaptée à ce phototype. Un praticien expérimenté avec les peaux mates à foncées adaptera son approche en conséquence ; c'est exactement pourquoi le plan de traitement est établi en personne, et non par un site web.",
    "faq.q8_title": "Le détatouage laser est-il douloureux et quelles options de gestion de la douleur existent ?",
    "faq.q8_body": "La plupart des personnes comparent la sensation du tir laser à un claquement d'élastique sur la peau accompagné d'une chaleur vive. Les zones traitées étant souvent sensibles, les praticiens recourent à plusieurs solutions d'atténuation : un flux continu d'air froid pulsé dirigé sur la zone avant, pendant et après chaque tir ; l'application préalable d'une crème anesthésiante locale 30 à 60 minutes avant la séance ; ainsi que des poches de froid. En milieu médical, des anesthésies locales par infiltration peuvent également être proposées pour les zones particulièrement sensibles.",
    "faq.q9_title": "Pourquoi les séances sont-elles espacées de plusieurs semaines et les traitements peuvent-ils être programmés plus tôt ?",
    "faq.q9_body": "Précipiter les séances n'accélère pas l'élimination et augmente le risque de lésions cutanées. Le laser fragmente l'encre en plus petits morceaux ; votre corps les élimine ensuite au cours des semaines suivantes. L'article de Kirby-Desai prévoyait 6 à 8 semaines entre les séances, et une grande étude (Bencini et al., 2012) a associé des intervalles de 8 semaines ou moins à un taux de réussite plus faible, de sorte que de nombreuses cliniques laissent désormais des intervalles plus longs. C'est votre clinique qui définit l'intervalle.",
