    "results.coverup_badge": "Stima preparatoria per cover-up",
    "results.coverup_note": "Il tuo obiettivo è lo sbiadimento per un cover-up. L'intervallo di sedute mostrato è per la rimozione completa; un cover-up di solito ne richiede meno. Molti artisti cercano uno sbiadimento del 50–70% circa (pratica del settore). Nessuno studio fornisce una frazione fissa di sedute, quindi la clinica e il tuo tatuatore decidono insieme quando è sufficientemente chiaro.",
    "results.referral_badge": "Oltre la soglia indicata dallo studio",
    "results.referral_note": "Lo studio Kirby-Desai pubblicato afferma che oltre i 15 punti un tatuaggio può essere difficile da rimuovere e che dovrebbe essere un medico a decidere se il laser è il metodo giusto. Il tuo punteggio supera questa soglia: porta questo risultato a una consulenza di persona con un medico laserista o dermatologo qualificato prima di dare per scontato che il laser sia l'approccio giusto.",
    "table.title": "Dettaglio punti Kirby-Desai",
    "table.col_factor": "Fattore di valutazione",
