    "calendar.interval_start": "Inizio",
    "calendar.interval_weeks": "+{weeks} sett",
    "calendar.ics_summary": "Seduta di rimozione tatuaggio laser #{num}",
    "calendar.ics_description": "Seduta prevista #{num} dal calcolatore di rimozione tatuaggi Poli International.\\nIntervallo della clinica: {interval} settimane.\\nProteggere scrupolosamente la pelle dal sole prima e dopo il trattamento.",
    "calendar.ics_completed_alert": "Tutte le sedute programmate risultano già completate.",
    "limits.title": "Cosa la scala Kirby-Desai non può prevedere",
    "limits.p1": "La scala Kirby-Desai fornisce un intervallo statistico di riferimento basato su uno studio retrospettivo su 100 pazienti. Non rappresenta una garanzia individuale. Quattro variabili cliniche non possono essere rilevate tramite questionario:",
    "limits.item_immune_title": "1. Risposta immunitaria individuale e fagocitosi linfatica",
    "limits.item_immune_desc": "I laser frantumano le particelle di inchiostro; sono i macrofagi dell'organismo e il sistema linfatico a smaltire fisicamente il pigmento. L'attività dei macrofagi e la velocità di espulsione metabolica variano notevolmente tra individui.",
    "limits.item_chemistry_title": "2. Chimica non regolamentata degli inchiostri e profondità del pigmento",
    "limits.item_chemistry_desc": "Gli inchiostri per tatuaggi sono miscele proprietarie di pigmenti, leganti e altri ingredienti, e la profondità raggiunta dall'ago varia. Entrambi modificano la risposta dell'inchiostro al laser.",
    "limits.item_smoking_title": "3. Fumo di sigaretta e microcircolazione",
    "limits.item_smoking_desc": "Uno studio su 352 pazienti (Bencini et al., Arch Dermatol 2012) ha rilevato che i fumatori avevano circa il 70% di probabilità in meno rispetto ai non fumatori di raggiungere la rimozione dopo 10 sedute. Gli autori suggeriscono che il fumo di sigaretta possa influenzare le cellule che eliminano il pigmento.",
    "limits.item_paradox_title": "4. Inchiostro bianco e scurimento paradosso",
    "limits.item_paradox_desc": "Inchiostri bianchi, color carne e cosmetici che contengono biossido di titanio o ossido di ferro possono diventare grigi o neri se trattati con il laser (scurimento paradosso), e tale scurimento può essere difficile da rimuovere.",
    "questions.title": "Domande per la tua clinica laser",
    "questions.subtitle": "Porta con te questa lista di verifica stampabile al tuo primo colloquio informativo:",
    "questions.q1_title": "1. Test preventivo (Patch test)",
    "questions.q1_body": "Eseguirete prima un piccolo test su un punto poco visibile per valutare la reazione della mia pelle e verificare l'assenza di scurimenti paradossi prima di trattare l'intero tatuaggio?",
    "questions.q2_title": "2. Spaziatura e intervalli tra le sedute",
    "questions.q2_body": "In che modo stabilite la distanza tra i trattamenti? Prolungheremo l'intervallo man mano che l'inchiostro sbiadisce per concedere al sistema immunitario il tempo necessario a smaltire i pigmenti?",
    "questions.q3_title": "3. Dettagli sui pigmenti e protezione della melanina",
    "questions.q3_body": "Quali lunghezze d'onda utilizzerete per i miei specifici colori di inchiostro, e quali precauzioni adottate per proteggere la melanina naturale della mia pelle da ipopigmentazione o iperpigmentazione?",
    "questions.q4_title": "4. Fasi di stallo e modifiche al protocollo",
    "questions.q4_body": "Qual è il vostro protocollo clinico se la rimozione raggiunge una fase di stallo o rallenta sensibilmente dopo diverse sedute?",
    "questions.q5_title": "5. Coordinamento per cover-up (se pertinente)",
    "questions.q5_body": "In caso di schiaritura per un cover-up, valuterete il tatuaggio insieme al mio tatuatore per stabilire il momento esatto in cui l'inchiostro è sufficientemente sbiadito per il nuovo disegno?",
    "fadelog.title": "Registro personale delle sedute e dello sbiadimento",
    "fadelog.subtitle": "Tieni un registro di ogni trattamento e del suo aspetto di sbiadimento, per il tuo professionista. Salvato solo nel tuo browser.",
