    "related.title": "Strumenti correlati per studi e clienti",
    "related.keloid_title": "Valutatore rischio cicatrici cheloidi",
    "related.keloid_desc": "Valuta la predisposizione a cicatrici ipertrofiche o cheloidi prima di sottoporti a procedure cutanee.",
    "related.ink_title": "Decodificatore ingredienti inchiostri",
    "related.ink_desc": "Consulta codici CI dei pigmenti, numeri di registro CAS e conformità EU REACH per i coloranti per tatuaggi.",
    "legal.disclaimer": "Avviso di riferimento clinico: Questo calcolatore applica l'algoritmo di punteggio clinico Kirby-Desai (Kirby W, Desai A, J Clin Aesthet Dermatol. 2009;2(3):32–37) a scopo puramente divulgativo e didattico. L'eliminazione effettiva varia in funzione della fagocitosi immunitaria individuale, della tecnologia del dispositivo laser (nanosecondi vs picosecondi), della perizia dell'operatore, della dimensione dello spot e della composizione chimica dei pigmenti. Questo strumento non costituisce consulenza medica e non garantisce la scomparsa totale del tatuaggio. Richiedi sempre un consulto specialistico di persona con un medico laserista o dermatologo qualificato.",
    "legal.print_disclaimer": "Scheda riassuntiva per la consulenza - Stampata dal calcolatore di sedute di rimozione tatuaggi di Poli International. Tutti i dati, le note e le tariffe sono inseriti a cura dell'utente.",
