    "aftercare.title": "Lista di controllo per la cura successiva",
    "aftercare.subtitle": "Un'attenta cura successiva riduce il rischio di infezione e alterazioni della pigmentazione. Le istruzioni della tua clinica hanno la precedenza.",
    "aftercare.stage1_title": "Fase 1: Guarigione acuta (Ore 0 a 48)",
    "aftercare.stage1_item1": "Applica impacchi freddi per 10-15 minuti alla volta per ridurre il gonfiore.",
    "aftercare.stage1_item2": "Solleva un braccio o una gamba trattati quando riposi per aiutare a ridurre il gonfiore.",
    "aftercare.stage1_item3": "Applica un sottile strato di vaselina o l'unguento fornito dalla tua clinica; non bucare né svuotare le vesciche.",
    "aftercare.stage1_item4": "Evita docce bollenti, saune, idromassaggi e sudorazione intensa per 48 ore.",
    "aftercare.stage2_title": "Fase 2: Riparazione dermica (Giorni 3 a 14)",
    "aftercare.stage2_item1": "Detergi delicatamente una volta al giorno con sapone neutro privo di profumo; tampona senza strofinare.",
    "aftercare.stage2_item2": "Non staccare o grattare le crosticine o la cute delle vescicole per scongiurare cicatrici e infezioni.",
    "aftercare.stage2_item3": "Indossa abiti morbidi e traspiranti per evitare sfregamenti continui sulla lesione.",
    "aftercare.stage3_title": "Fase 3: Protezione solare (Da 2 a 8+ settimane)",
    "aftercare.stage3_item1": "Usa una protezione solare ad ampio spettro (SPF 30 o superiore) o mantieni l'area coperta per ridurre il rischio di alterazioni della pigmentazione.",
    "aftercare.stage3_item2": "Segui eventuali istruzioni extra dalla tua clinica, come ad esempio quando potrai nuotare o fare esercizio fisico di nuovo.",
    "aftercare.stage3_item3": "Attendi l'intervallo completo consigliato dalla tua clinica prima della sessione laser successiva.",
