    "trajectory.score_note": "Punteggio Kirby-Desai: {score} pt | Intervallo target: da {min} a {max} sedute",
    "faq.title": "Domande cliniche frequenti",
    "faq.subtitle": "Risposte su come funziona la rimozione laser, la preparazione e i plateau. I consigli della tua clinica hanno la precedenza.",
    "faq.expand_all": "Espandi tutto",
    "faq.collapse_all": "Comprimi tutto",
    "faq.direct_link": "Link diretto a questa domanda",
    "faq.link_copied": "Link diretto copiato negli appunti",
    "faq.q1_title": "Cosa succede se il trattamento laser smette di dare risultati o raggiunge una fase di stallo?",
    "faq.q1_body": "Un plateau di sbiadimento si verifica spesso quando l'inchiostro che si frammenta facilmente è stato rimosso, lasciando pigmenti più profondi o ostinati. Quando lo sbiadimento si blocca, il tuo operatore potrebbe cambiare approccio per ciò che rimane o lasciare intervalli più lunghi tra le sedute (spesso 12 settimane o più, una pratica comune nelle cliniche) per dare al corpo più tempo per eliminare i frammenti. Qualsiasi eventuale cambiamento è una decisione che il tuo operatore prende di persona, non qualcosa che questo strumento può specificare.",
    "faq.q2_title": "Come devo preparare la pelle prima di una seduta di rimozione laser?",
    "faq.q2_body": "Le cliniche chiedono comunemente di evitare l'esposizione al sole, i lettini abbronzanti e gli autoabbronzanti per diverse settimane prima del trattamento (spesso 4 settimane o più; segui la regola della tua clinica), poiché la pelle abbronzata compete con l'inchiostro per l'energia del laser e aumenta il rischio di alterazioni della pigmentazione. Molti chiedono anche di radere l'area il giorno prima, di arrivare con la pelle pulita senza cosmetici, creme idratanti o deodorante, e di usare la crema anestetica solo se viene indicato. Alcuni chiedono di evitare alcol e aspirina in anticipo. Queste sono pratiche cliniche: le istruzioni del tuo operatore hanno la precedenza.",
    "faq.q3_title": "Perché gli inchiostri colorati (verde, blu, giallo) richiedono laser diversi rispetto al nero?",
    "faq.q3_body": "La rimozione laser funziona perché il pigmento assorbe l'energia luminosa e si frammenta in particelle che il corpo può eliminare; una data lunghezza d'onda è efficace solo se il pigmento bersaglio la assorbe davvero. L'inchiostro nero assorbe una gamma molto ampia di luce e generalmente risponde in modo più affidabile. I pigmenti rosso, blu, verde e viola assorbono in modo più ristretto, e il giallo è notoriamente il colore più difficile da eliminare perché assorbe male la luce nella finestra sicura per la pelle. È esattamente per questo che un tatuaggio multicolore richiede spesso più sedute di uno nero pieno. La scelta del laser e della lunghezza d'onda per i tuoi colori specifici è una decisione clinica presa di persona dal tuo professionista, non da questo strumento.",
    "faq.q4_title": "L'inchiostro bianco o i pigmenti per trucco permanente possono diventare neri col laser?",
    "faq.q4_body": "Sì. Questo fenomeno è noto come scurimento paradosso. Molti pigmenti bianchi, color carne e cosmetici contengono biossido di titanio o ossido di ferro. L'impulso laser può alterare chimicamente questi pigmenti, facendo sì che l'inchiostro bianco, rosa o color pelle diventi grigio o nero, e tale scurimento può essere difficile da rimuovere. Per questo motivo i professionisti testano una piccola macchia su inchiostro cosmetico o bianco prima di trattare l'intera area.",
    "faq.q5_title": "Quanto influisce il fumo di tabacco sul numero di sedute necessarie?",
    "faq.q5_body": "Uno studio su 352 pazienti a Milano (Bencini et al., Archives of Dermatology, 2012) ha rilevato che i fumatori avevano circa il 70% di probabilità in meno rispetto ai non fumatori di raggiungere la rimozione dopo 10 sedute. Gli autori suggeriscono che le sostanze nel fumo di sigaretta possano influenzare le cellule che eliminano il pigmento frammentato. Si tratta di uno studio e ha misurato la probabilità di successo, non un numero di sedute extra, quindi questo strumento non aggiunge una percentuale di fumo alla tua stima.",
    "faq.q6_title": "Quando un tatuaggio è sufficientemente schiarito per una cover-up?",
    "faq.q6_body": "Molti tatuatori cercano uno sbiadimento approssimativo dal 50% al 70% prima di un cover-up, anziché la rimozione completa (pratica del settore). Un cover-up richiede solitamente meno sedute rispetto alla rimozione completa, ma nessuno studio fornisce un numero fisso. Lavora con il tuo tatuatore: una volta che i contorni scuri sono sbiaditi fino a un grigio tenue, l'artista può solitamente progettarci sopra senza che il vecchio lavoro traspaia. Regola pratica dello studio: attendi almeno da 8 a 12 settimane dopo l'ultima sessione laser, finché la pelle non è completamente guarita, prima di tatuare.",
    "faq.q7_title": "In che modo il fototipo di Fitzpatrick influisce sulla sicurezza e sui tempi del laser?",
    "faq.q7_body": "I fototipi di Fitzpatrick da I a III hanno meno melanina epidermica, il che generalmente lascia al professionista più margine di manovra senza alterare il colore della pelle circostante. I fototipi da IV a VI contengono più melanina naturale, che compete con il pigmento del tatuaggio per l'energia del laser e aumenta il rischio che la pelle stessa si scurisca o si schiarisca (iperpigmentazione o ipopigmentazione) se l'approccio non viene adattato a quel fototipo. Un professionista esperto con pelli scure adatterà il proprio approccio di conseguenza; è esattamente per questo che il piano di trattamento viene stabilito di persona, non da un sito web.",
    "faq.q8_title": "La rimozione laser dei tatuaggi è dolorosa e quali opzioni di gestione del dolore sono disponibili?",
    "faq.q8_body": "La maggior parte delle persone descrive la sensazione del raggio laser come lo scocco di un elastico sulla pelle unito a un calore intenso. Poiché le aree trattate sono spesso sensibili, le cliniche impiegano diverse strategie di attenuazione: getti d'aria fredda forzata continua diretti sull'area prima, durante e dopo l'impulso; creme anestetiche topiche applicate 30-60 minuti prima della seduta; e impacchi di ghiaccio. In ambito medico possono essere praticate infiltrazioni locali per zone anatomiche particolarmente delicate.",
    "faq.q9_title": "Perché le sedute sono distanziate di settimane e i trattamenti possono essere programmati prima?",
    "faq.q9_body": "Affrettare le sedute non accelera la rimozione e aumenta il rischio di danni alla pelle. Il laser frammenta l'inchiostro in pezzi più piccoli; il tuo corpo li elimina poi nelle settimane successive. L'articolo di Kirby-Desai considerava da 6 a 8 settimane tra le sedute, e un grande studio (Bencini et al., 2012) ha associato intervalli di 8 settimane o meno a un minor successo, motivo per cui molte cliniche ora lasciano intervalli più lunghi. La tua clinica stabilisce l'intervallo.",
