    "results.dominant_intro": "Hauptfaktor: ",
    "results.dominant_location": "Die Platzierung an einer distalen Extremität ({pts} Pkt.) verlangsamt den Abbau durch die begrenzte periphere Lymphzirkulation.",
    "results.dominant_skin": "Dunklerer Hautfototyp ({pts} Pkt.): Der Behandler muss konservativer vorgehen, um die natürliche Hautfarbe zu schützen, weshalb die Entfernung in der Regel mehr Sitzungen erfordert.",
    "results.dominant_colour": "Mehrfarbige Tinte ({pts} Pkt.): Unterschiedliche Farben absorbieren unterschiedliche Wellenlängen, daher ist oft mehr als eine Lasereinstellung erforderlich.",
    "results.dominant_density": "Hohes Tintevolumen ({pts} Pkt.): Mehr Pigment bedeutet in der Regel mehr Sitzungen.",
    "results.dominant_scarring": "Narbenbildung oder Gewebeveränderung ({pts} Pkt.) macht die Entfernung langsamer und schwieriger.",
    "results.dominant_layering": "Übereinandergelegte Cover-up-Arbeit ({pts} Pkt.): Zwei Schichten Tinte, daher mehr Sitzungen.",
    "results.coverup_badge": "Schätzung zur Cover-up-Vorbereitung",
    "results.coverup_note": "Ihr Ziel ist eine Verblassung für ein Cover-up. Der angezeigte Sitzungsbereich gilt für die vollständige Entfernung; ein Cover-up erfordert in der Regel weniger. Viele Tätowierer streben eine Verblassung von ca. 50–70% an (Branchenpraxis). Keine Studie nennt einen festen Bruchteil der Sitzungen, daher entscheiden Ihre Klinik und Ihr Tätowierer gemeinsam, wann es hell genug ist.",
    "results.referral_badge": "Über dem im Paper genannten Schwellenwert",
    "results.referral_note": "Die veröffentlichte Kirby-Desai-Studie besagt, dass ein Tattoo oberhalb von 15 Punkten schwer zu entfernen sein kann und ein Arzt entscheiden sollte, ob Laser die richtige Methode ist. Ihr Wert liegt über diesem Schwellenwert: Bringen Sie dieses Ergebnis zu einer persönlichen Beratung bei einem lizenzierten Laserspezialisten oder Dermatologen mit, bevor Sie eine Laserentfernung als die naheliegende Lösung annehmen.",
    "table.title": "Aufschlüsselung der Kirby-Desai-Punkte",
