    "calendar.ics_summary": "Laser-Tattooentfernung Sitzung #{num}",
    "calendar.ics_description": "Voraussichtliche Sitzung #{num} aus dem Poli International Tattooentfernungs-Rechner.\\nPraxisintervall: {interval} Wochen.\\nHautareal vor und nach der Behandlung konsequent vor UV-Licht schützen.",
    "calendar.ics_completed_alert": "Alle geplanten Sitzungen sind bereits als abgeschlossen eingetragen.",
    "limits.title": "Was die Kirby-Desai-Skala nicht vorhersagen kann",
    "limits.p1": "Die Kirby-Desai-Skala liefert einen statistischen Referenzbereich basierend auf einer retrospektiven Studie an 100 Patienten. Sie stellt keine individuelle Garantie dar. Vier klinische Variablen können durch einen Fragebogen nicht erfasst werden:",
    "limits.item_immune_title": "1. Individuelle Phagozytose durch Immunsystem und Lymphbahnen",
    "limits.item_immune_desc": "Laser zertrümmern die Farbpartikel; der eigentliche Abbau erfolgt durch die Makrophagen und das Lymphsystem Ihres Körpers. Die Makrophagenaktivität und die metabolische Abbaugeschwindigkeit unterscheiden sich individuell stark.",
    "limits.item_chemistry_title": "2. Unregulierte Farbchemie und Pigmenttiefe",
    "limits.item_chemistry_desc": "Tattoofarben sind proprietäre Mischungen aus Pigmenten, Bindemitteln und anderen Inhaltsstoffen, und die erreichte Tiefe der Nadel variiert. Beides beeinflusst, wie die Tinte auf den Laser reagiert.",
    "limits.item_smoking_title": "3. Rauchen und Mikrozirkulation",
    "limits.item_smoking_desc": "Eine Studie mit 352 Patienten (Bencini et al., Arch Dermatol 2012) ergab, dass Raucher nach 10 Sitzungen eine etwa 70% geringere Wahrscheinlichkeit hatten, eine vollständige Entfernung zu erreichen, als Nichtraucher. Die Autoren vermuten, dass Zigarettenrauch die Zellen beeinträchtigen kann, die das Pigment abbauen.",
    "limits.item_paradox_title": "4. Weiße Tattoofarbe und paradoxes Nachdunkeln",
    "limits.item_paradox_desc": "Weiße, hautfarbene und kosmetische Tinten, die Titandioxid oder Eisenoxid enthalten, können durch das Lasern grau oder schwarz werden (paradoxe Nachdunklung), und diese Nachdunklung kann schwer zu entfernen sein.",
    "questions.title": "Fragen an Ihre Laserpraxis",
    "questions.subtitle": "Nehmen Sie diese ausdruckbare Checkliste zu Ihrem ersten Beratungsgespräch mit:",
    "questions.q1_title": "1. Probelasern (Patch-Test)",
    "questions.q1_body": "Führen Sie vorab einen kleinen Testschuss an einer unauffälligen Stelle durch, um meine Hautreaktion zu prüfen und ein paradoxes Nachdunkeln auszuschließen, bevor das gesamte Tattoo behandelt wird?",
    "questions.q2_title": "2. Sitzungsabstände und Intervalle",
    "questions.q2_body": "Wie legen Sie die Abstände zwischen den Sitzungen fest? Werden die Intervalle mit zunehmender Aufhellung verlängert, um dem Immunsystem ausreichend Zeit für den Pigmentabtransport zu geben?",
    "questions.q3_title": "3. Pigment-Besonderheiten und Melaninschutz",
    "questions.q3_body": "Welche Laserwellenlängen setzen Sie für meine speziellen Tattoofarben ein und welche Schutzmaßnahmen ergreifen Sie, um mein natürliches Hautmelanin vor Hypo- oder Hyperpigmentierung zu bewahren?",
    "questions.q4_title": "4. Aufhellungsstillstand und Protokollanpassungen",
    "questions.q4_body": "Welches klinische Vorgehen greift bei Ihnen, falls die Aufhellung nach mehreren Sitzungen stagniert oder ein Plateau erreicht?",
    "questions.q5_title": "5. Zusammenarbeit mit dem Tätowierer (bei Cover-up)",
    "questions.q5_body": "Falls für ein Cover-up aufgehellt wird: Stimmen Sie sich mit meinem Tätowierer ab, um den exakten Zeitpunkt zu bestimmen, an dem der Grad der Aufhellung für ein neues Motiv optimal ausreicht?",
