    "legal.disclaimer": "Klinischer Referenzhinweis: Dieser Rechner wendet den klinischen Kirby-Desai-Scoring-Algorithmus (Kirby W, Desai A, J Clin Aesthet Dermatol. 2009;2(3):32–37) als didaktischen Orientierungsleitfaden an. Die tatsächliche Sitzungsanzahl variiert mit der individuellen Immunphagozytose, der Lasertechnologie (Nanosekunden vs. Pikosekunden), der Anwendertechnik, Spotgröße und chemischen Pigmentzusammensetzung. Dieses Tool stellt keine medizinische Beratung dar und garantiert keine rückstandsfreie Entfernung. Vereinbaren Sie stets ein persönliches Beratungsgespräch mit einem qualifizierten Lasermediziner oder Dermatologen.",
    "legal.print_disclaimer": "Klienten-Beratungsbogen - Gedruckt mit dem Poli International Tattooentfernungs-Sitzungsrechner. Alle Einträge, Notizen und Preise basieren auf den Angaben des Klienten.",
