    "aftercare.title": "Pflege-Checkliste",
    "aftercare.subtitle": "Sorgfältige Nachsorge senkt das Risiko von Infektionen und Pigmentveränderungen. Die Anweisungen Ihrer Klinik haben Vorrang.",
    "aftercare.stage1_title": "Phase 1: Akute Heilung (Stunden 0 bis 48)",
    "aftercare.stage1_item1": "Tragen Sie jeweils 10 bis 15 Minuten lang kalte Kompressen auf, um Schwellungen zu reduzieren.",
    "aftercare.stage1_item2": "Lagern Sie einen behandelten Arm oder ein behandeltes Bein beim Ausruhen hoch, um Schwellungen zu reduzieren.",
    "aftercare.stage1_item3": "Tragen Sie eine dünne Schicht Vaseline oder die von Ihrer Klinik ausgehändigte Salbe auf; stechen oder öffnen Sie keine Blasen.",
    "aftercare.stage1_item4": "Heiße Duschen, Saunen, Whirlpools und schweißtreibende Aktivitäten für 48 Stunden meiden.",
    "aftercare.stage2_title": "Phase 2: Dermale Regeneration (Tage 3 bis 14)",
    "aftercare.stage2_item1": "Einmal täglich sanft mit milder parfümfreier Seife reinigen; nur vorsichtig abtupfen.",
    "aftercare.stage2_item2": "Krusten oder Blasenhäute niemals abkratzen oder abziehen, um Narben und Infektionen vorzubeugen.",
    "aftercare.stage2_item3": "Weite, atmungsaktive Kleidung tragen, um Reibung an der Hautpartie zu vermeiden.",
    "aftercare.stage3_title": "Stufe 3: Sonnenschutz (Woche 2 bis 8+)",
    "aftercare.stage3_item1": "Verwenden Sie ein Breitspektrum-Sonnenschutzmittel (LSF 30 oder höher) oder halten Sie den Bereich bedeckt, um das Risiko von Pigmentveränderungen zu verringern.",
    "aftercare.stage3_item2": "Befolgen Sie alle zusätzlichen Anweisungen Ihrer Klinik, z. B. wann Sie wieder schwimmen oder Sport treiben dürfen.",
    "aftercare.stage3_item3": "Warten Sie vor der nächsten Lasersitzung das vollständige, von Ihrer Klinik empfohlene Intervall ab.",
