    "faq.title": "Häufig gestellte klinische Fragen",
    "faq.subtitle": "Antworten zur Funktionsweise der Laserentfernung, Vorbereitung und Plateaus. Der Rat Ihrer Klinik hat Vorrang.",
    "faq.expand_all": "Alle aufklappen",
    "faq.collapse_all": "Alle einklappen",
    "faq.direct_link": "Direktlink zu dieser Frage",
    "faq.link_copied": "Direktlink in die Zwischenablage kopiert",
    "faq.q1_title": "Was geschieht, wenn die Tattooentfernung stagniert oder ein Aufhellungsplateau erreicht?",
    "faq.q1_body": "Ein Verblassungsplateau tritt oft auf, wenn die leicht zu zersetzende Tinte abgebaut ist und tiefere oder hartnäckigere Pigmente zurückbleiben. Wenn die Verblassung ins Stocken gerät, kann Ihr Behandler das Vorgehen für die Reste ändern oder längere Abstände zwischen den Sitzungen einhalten (häufig 12 Wochen oder mehr, eine gängige Praxis in Kliniken), um dem Körper mehr Zeit zum Abtransport der Fragmente zu geben. Ob und was sich ändert, entscheidet Ihr Behandler persönlich und nicht dieses Tool.",
    "faq.q2_title": "Wie sollte ich meine Haut auf eine Laser-Tattooentfernung vorbereiten?",
    "faq.q2_body": "Kliniken empfehlen in der Regel, mehrere Wochen vor der Behandlung (oft 4 Wochen oder mehr; befolgen Sie die Regeln Ihrer Klinik) auf Sonnenbäder, Solarien und Selbstbräuner zu verzichten, da gebräunte Haut mit der Tinte um die Laserenergie konkurriert und das Risiko von Pigmentveränderungen erhöht. Viele bitten Sie auch, den Bereich am Tag zuvor zu rasieren, mit sauberer Haut ohne Kosmetika, Feuchtigkeitscremes oder Deodorant zu erscheinen und Betäubungscreme nur auf Anweisung zu verwenden. Einige raten dazu, vorher keinen Alkohol und kein Aspirin zu konsumieren. Dies sind klinische Praktiken: Die Anweisungen Ihres Behandlers haben Vorrang.",
    "faq.q3_title": "Warum erfordern bunte Farben (Grün, Blau, Gelb) andere Laser als Schwarz?",
    "faq.q3_body": "Die Laserentfernung funktioniert, weil ein Pigment Lichtenergie absorbiert und in Partikel zerfällt, die der Körper abtransportieren kann; eine bestimmte Wellenlänge wirkt nur, wenn das Zielpigment sie tatsächlich absorbiert. Schwarze Tinte absorbiert ein sehr breites Lichtspektrum und spricht in der Regel am zuverlässigsten an. Rote, blaue, grüne und violette Pigmente absorbieren enger, und Gelb gilt bekanntermaßen als die am schwierigsten zu entfernende Farbe, da es Licht im für die Haut sicheren Bereich nur schlecht absorbiert. Genau deshalb benötigt mehrfarbige Arbeit oft mehr Sitzungen als reines Schwarz. Welchen Laser und welche Wellenlänge Ihr Behandler für Ihre spezifischen Farben wählt, ist eine klinische Entscheidung, die persönlich getroffen wird, nicht von diesem Tool.",
    "faq.q4_title": "Kann weiße Tinte oder Permanent-Make-up beim Lasern schwarz werden?",
    "faq.q4_body": "Ja. Dies wird als paradoxe Nachdunklung bezeichnet. Weiße, hautfarbene und viele kosmetische Pigmente enthalten Titandioxid oder Eisenoxid. Der Laserimpuls kann diese Pigmente chemisch verändern, sodass weiße, rosa oder hautfarbene Tinte grau oder schwarz wird, und diese Nachdunklung kann schwer zu entfernen sein. Aus diesem Grund testen Behandler vor der Behandlung des gesamten Bereichs eine kleine Stelle bei kosmetischer oder weißer Tinte.",
    "faq.q5_title": "Wie stark beeinflusst Tabakkonsum die Anzahl der erforderlichen Sitzungen?",
    "faq.q5_body": "Eine Studie mit 352 Patienten in Mailand (Bencini et al., Archives of Dermatology, 2012) ergab, dass Raucher eine ca. 70% geringere Wahrscheinlichkeit als Nichtraucher hatten, die Entfernung nach 10 Sitzungen zu erreichen. Die Autoren vermuten, dass Substanzen im Zigarettenrauch die Zellen beeinträchtigen können, die das zerkleinerte Pigment abbauen. Es handelt sich um eine einzelne Studie, die die Erfolgswahrscheinlichkeit und nicht die Anzahl zusätzlicher Sitzungen gemessen hat, weshalb dieses Tool keinen Raucher-Prozentsatz zu Ihrer Schätzung hinzurechnet.",
    "faq.q6_title": "Wann ist ein Tattoo ausreichend aufgehellt für ein Cover-up statt einer Komplettentfernung?",
    "faq.q6_body": "Viele Tätowierer streben vor einem Cover-up eine Verblassung von ca. 50% bis 70% an, anstatt einer vollständigen Entfernung (Branchenpraxis). Ein Cover-up erfordert in der Regel weniger Sitzungen als eine vollständige Entfernung, aber keine Studie nennt eine feste Anzahl. Arbeiten Sie mit Ihrem Tätowierer zusammen: Sobald dunkle Outlines zu einem sanften Grau verblasst sind, kann der Tätowierer in der Regel darüber entwerfen, ohne dass das alte Werk durchschimmert. Studio-Faustregel: Warten Sie vor dem Tätowieren mindestens 8 bis 12 Wochen nach Ihrer letzten Lasersitzung, bis die Haut vollständig verheilt ist.",
    "faq.q7_title": "Wie beeinflusst mein Fitzpatrick-Hauttyp die Sicherheit und Behandlungsdauer?",
    "faq.q7_body": "Die Fitzpatrick-Hauttypen I bis III haben weniger epidermales Melanin, was dem Behandler in der Regel mehr Spielraum lässt, ohne die umgebende Hautfarbe zu beeinträchtigen. Die Hauttypen IV bis VI enthalten mehr natürliches Melanin, das mit dem Tattoo-Pigment um die Laserenergie konkurriert und das Risiko erhöht, dass sich die Haut selbst verdunkelt oder aufhellt (Hyper- oder Hypopigmentierung), wenn der Ansatz nicht an diesen Hauttyp angepasst wird. Ein mit dunkleren Hauttypen erfahrener Behandler passt seinen Ansatz entsprechend an; genau deshalb wird der Behandlungsplan persönlich festgelegt, nicht von einer Website.",
    "faq.q8_title": "Ist die Laser-Tattooentfernung schmerzhaft und welche Methoden zur Schmerzlinderung gibt es?",
    "faq.q8_body": "Die meisten Behandelten vergleichen das Schmerzempfinden eines Laserpulses mit dem Schnappen eines Gummibands auf der Haut, begleitet von einem kurzen Hitzeimpuls. Da Tätowierstellen empfindlich sein können, setzen Fachpraxen mehrere Methoden zur Schmerzminderung ein: kontinuierliche Kaltluftkühlung direkt vor, während und nach den Laserimpulsen; das Auftragen lokalanästhetischer Cremes 30 bis 60 Minuten vor der Behandlung; sowie Kältekompressen. In ärztlich geführten Praxen können für besonders schmerzempfindliche Stellen auch lokale Infiltrationen erfolgen.",
    "faq.q9_title": "Warum liegen Wochen zwischen den Sitzungen und können Behandlungen früher angesetzt werden?",
    "faq.q9_body": "Ein Übereilen der Sitzungen beschleunigt die Entfernung nicht und erhöht das Risiko von Hautschäden. Der Laser zerkleinert die Tinte in kleinere Fragmente; Ihr Körper baut diese dann in den folgenden Wochen ab. Der Kirby-Desai-Artikel ging von 6 bis 8 Wochen zwischen den Sitzungen aus, und eine große Studie (Bencini et al., 2012) brachte Intervalle von 8 Wochen oder weniger mit geringeren Erfolgsaussichten in Verbindung, weshalb viele Kliniken inzwischen längere Pausen einlegen. Ihre Klinik legt das Intervall fest.",
