    "results.coverup_badge": "Estimación de preparación para cover-up",
    "results.coverup_note": "Tu objetivo es el aclarado para un trabajo de cobertura. El rango de sesiones mostrado es para la eliminación completa; un trabajo de cobertura suele necesitar menos. Muchos artistas buscan un aclarado de entre el 50 y el 70 % (práctica de la industria). Ningún estudio ofrece una fracción fija de sesiones, por lo que tu clínica y tu artista deciden juntos cuándo está lo suficientemente claro.",
    "results.referral_badge": "Por encima del umbral del propio estudio",
    "results.referral_note": "El estudio publicado de Kirby-Desai indica que, por encima de 15 puntos, un tatuaje puede ser difícil de eliminar y que debe ser un médico quien decida si el láser es el método adecuado. Su puntuación supera ese umbral: lleve este resultado a una consulta presencial con un especialista en láser o dermatólogo colegiado antes de asumir que la eliminación con láser es el enfoque evidente.",
