    "limits.title": "Lo que la escala Kirby-Desai no puede prever",
    "limits.p1": "La escala Kirby-Desai proporciona un rango estadístico de referencia a partir de un estudio retrospectivo de 100 pacientes. No es una garantía individual. Cuatro factores clínicos no pueden medirse mediante un cuestionario:",
    "limits.item_immune_title": "1. Respuesta inmunitaria y fagocitosis linfática individual",
    "limits.item_immune_desc": "El láser fragmenta la tinta; son los macrófagos y el sistema linfático del organismo los que eliminan las partículas. La tasa metabólica de aclarado varía notablemente entre personas.",
    "limits.item_chemistry_title": "2. Composición química de tintas no regulada y profundidad",
    "limits.item_chemistry_desc": "Las tintas para tatuajes son mezclas patentadas de pigmentos, aglutinantes y otros ingredientes, y la profundidad a la que llegó la aguja varía. Ambas cosas cambian la forma en que la tinta responde al láser.",
    "limits.item_smoking_title": "3. Tabaquismo y microcirculación",
    "limits.item_smoking_desc": "Un estudio de 352 pacientes (Bencini et al., Arch Dermatol 2012) descubrió que los fumadores tenían un 70 % menos de probabilidades que los no fumadores de lograr la eliminación después de 10 sesiones. Los autores sugieren que el humo del cigarrillo puede afectar a las células que eliminan el pigmento.",
    "limits.item_paradox_title": "4. Tinta blanca y oscurecimiento paradójico",
    "limits.item_paradox_desc": "Las tintas blancas, del tono de la carne y cosméticas que contienen dióxido de titanio u óxido de hierro pueden volverse grises o negras al recibir láser (oscurecimiento paradójico), y ese oscurecimiento puede ser difícil de eliminar.",
    "questions.title": "Preguntas clave para tu clínica láser",
    "questions.subtitle": "Lleva esta lista de consulta imprimible a tu primera cita informativa:",
    "questions.q1_title": "1. Prueba preliminar (Spot test)",
    "questions.q1_body": "¿Realizaréis una pequeña prueba previa en una zona poco visible para evaluar la respuesta de mi piel y descartar oscurecimientos paradójicos antes de tratar el tatuaje completo?",
    "questions.q2_title": "2. Espaciado entre sesiones e intervalos",
    "questions.q2_body": "¿Cómo determináis el tiempo entre sesiones? ¿Alargaremos el intervalo conforme la tinta se aclare para dar tiempo al sistema inmunitario a drenar los pigmentos fragmentados?",
    "questions.q3_title": "3. Especificaciones de longitud de onda y melanina",
    "questions.q3_body": "¿Qué longitudes de onda láser emplearéis para mis colores concretos, y qué precauciones tomáis para proteger la melanina natural de mi piel de hipo o hiperpigmentaciones?",
    "questions.q4_title": "4. Fases de estancamiento del aclarado",
    "questions.q4_body": "¿Cuál es el protocolo de la clínica si el aclarado del tatuaje se estanca o avanza con lentitud tras varias sesiones?",
    "questions.q5_title": "5. Coordinación para cover-up (si procede)",
    "questions.q5_body": "Si el objetivo es aclarar para un cover-up, ¿valoraréis la evolución junto con mi tatuador para fijar el momento idóneo en que la piel admita el nuevo diseño sin problemas?",
