    "related.ink_desc": "Consulta números CI de pigmentos, códigos CAS y conformidad EU REACH para tintas de tatuaje.",
    "legal.disclaimer": "Aviso de referencia clínica: Este estimador aplica el algoritmo de puntuación clínica Kirby-Desai (Kirby W, Desai A, J Clin Aesthet Dermatol. 2009;2(3):32–37) con fines exclusivamente divulgativos y formativos. La eliminación real varía en función de la fagocitosis inmunitaria individual, la tecnología del láser (nanosegundos vs picosegundos), la destreza profesional, el tamaño del haz y la química del pigmento. Esta herramienta no constituye consejo médico ni garantiza el borrado total. Consulta siempre en persona a un médico o dermatólogo especialista en láser.",
