    "aftercare.title": "Lista de comprobación de cuidados posteriores",
    "aftercare.subtitle": "Unos buenos cuidados posteriores reducen el riesgo de infección y cambios de pigmentación. Las propias instrucciones de tu clínica tienen prioridad.",
    "aftercare.stage1_title": "Fase 1: Cicatrización aguda (Horas 0 a 48)",
    "aftercare.stage1_item1": "Aplica compresas frías durante 10 a 15 minutos cada vez para reducir la inflamación.",
    "aftercare.stage1_item2": "Eleva el brazo o la pierna tratados al descansar para ayudar a reducir la inflamación.",
    "aftercare.stage1_item3": "Aplica una capa fina de vaselina o la pomada que te dé tu clínica; no revientes ni drenes las ampollas.",
    "aftercare.stage1_item4": "Evite duchas calientes, saunas, baños termales y sudoración intensa durante 48 horas.",
    "aftercare.stage2_title": "Fase 2: Recuperación dérmica (Días 3 a 14)",
    "aftercare.stage2_item1": "Limpie con suavidad una vez al día con jabón neutro sin fragancias; seque con toques suaves.",
    "aftercare.stage2_item2": "No arranque, rasque ni desprenda costras o ampollas secas para prevenir cicatrices e infecciones.",
    "aftercare.stage2_item3": "Use prendas holgadas y transpirables para evitar la fricción mecánica sobre la zona.",
    "aftercare.stage3_title": "Etapa 3: Protección solar (Semanas 2 a 8+)",
    "aftercare.stage3_item1": "Usa un protector solar de amplio espectro (SPF 30 o superior) o mantén la zona cubierta para reducir el riesgo de cambios de pigmentación.",
    "aftercare.stage3_item2": "Sigue cualquier instrucción adicional de tu clínica, como cuándo puedes volver a nadar o hacer ejercicio.",
    "aftercare.stage3_item3": "Deja pasar el intervalo completo que recomienda tu clínica antes de la siguiente sesión de láser.",
