    "trajectory.status_clearance": "Cerca de la eliminación completa (95 %+ en esta curva)",
    "trajectory.actual_observed": "Su progreso registrado: Sesión {sess} ({pct}% aclarado)",
    "trajectory.score_note": "Puntuación Kirby-Desai: {score} pts | Rango estimado: {min} a {max} sesiones",
    "faq.title": "Preguntas clínicas frecuentes",
    "faq.subtitle": "Respuestas sobre cómo funciona la eliminación con láser, la preparación y los estancamientos. El consejo de tu clínica es lo primero.",
    "faq.expand_all": "Expandir todo",
    "faq.collapse_all": "Contraer todo",
    "faq.direct_link": "Enlace directo a esta pregunta",
    "faq.link_copied": "Enlace directo copiado al portapapeles",
    "faq.q1_title": "¿Qué sucede si el tratamiento láser deja de mostrar avances o se estanca en una meseta?",
    "faq.q1_body": "A menudo se produce un estancamiento en el aclarado cuando la tinta que se descompone fácilmente ha desaparecido, dejando atrás un pigmento más profundo o persistente. Cuando el aclarado se detiene, tu proveedor puede cambiar su enfoque para lo que queda, o dejar intervalos más largos entre sesiones (a menudo 12 semanas o más, una práctica común en las clínicas) para darle al cuerpo más tiempo para eliminar los fragmentos. Qué cambios hacer, si es que se hace alguno, es una decisión que tu proveedor toma en persona, no algo que esta herramienta pueda especificar.",
    "faq.q2_title": "¿Cómo debo preparar mi piel antes de una sesión de eliminación láser?",
    "faq.q2_body": "Las clínicas suelen pedir que evites la exposición al sol, las camas de bronceado y los autobronceadores durante varias semanas antes del tratamiento (a menudo 4 semanas o más; sigue la norma de tu clínica), porque la piel bronceada compite con la tinta por la energía del láser y aumenta el riesgo de cambios de pigmentación. Muchos también piden que afeites la zona el día anterior, acudas con la piel limpia y sin cosméticos, cremas hidratantes o desodorante, y uses crema anestésica solo si te lo indican. Algunos piden que evites el alcohol y la aspirina de antemano. Estas son prácticas de las clínicas: las instrucciones de tu proveedor son lo primero.",
    "faq.q3_title": "¿Por qué las tintas de colores (verde, azul, amarillo) requieren láseres distintos al negro?",
    "faq.q3_body": "La eliminación con láser funciona porque un pigmento absorbe energía lumínica y se fragmenta en partículas que el cuerpo puede eliminar; una longitud de onda determinada solo es eficaz si el pigmento objetivo la absorbe realmente. La tinta negra absorbe una gama muy amplia de luz y por lo general responde de forma más fiable. Los pigmentos rojo, azul, verde y morado absorben de forma más limitada, y el amarillo es notoriamente el color más difícil de eliminar porque absorbe mal la luz dentro del rango seguro para la piel. Por eso mismo, un tatuaje multicolor suele necesitar más sesiones que uno en negro sólido. Qué láser y qué longitud de onda elige su especialista para sus colores concretos es una decisión clínica tomada en persona, no por esta herramienta.",
    "faq.q4_title": "¿Puede la tinta blanca o el maquillaje permanente volverse negro con el láser?",
    "faq.q4_body": "Sí. Esto se llama oscurecimiento paradójico. Los pigmentos blancos, del tono de la piel y muchos cosméticos contienen dióxido de titanio u óxido de hierro. El pulso del láser puede cambiar químicamente estos pigmentos, de modo que la tinta blanca, rosa o del tono de la piel se vuelve gris o negra, y ese oscurecimiento puede ser difícil de eliminar. Es por esto que los profesionales prueban una pequeña mancha en tinta cosmética o blanca antes de tratar toda la zona.",
    "faq.q5_title": "¿Cuánto influye el consumo de tabaco en la cantidad de sesiones requeridas?",
    "faq.q5_body": "Un estudio de 352 pacientes en Milán (Bencini et al., Archives of Dermatology, 2012) descubrió que los fumadores tenían aproximadamente un 70 % menos de probabilidades que los no fumadores de lograr la eliminación después de 10 sesiones. Los autores sugieren que las sustancias del humo del cigarrillo pueden afectar a las células que eliminan el pigmento descompuesto. Es un estudio y midió la probabilidad de éxito, no un número de sesiones adicionales, por lo que esta herramienta no añade un porcentaje de tabaquismo a tu estimación.",
    "faq.q6_title": "¿Cuándo está un tatuaje lo bastante aclarado para un cover-up en vez de eliminación completa?",
    "faq.q6_body": "Muchos tatuajistas buscan un aclarado de aproximadamente el 50 % al 70 % antes de un trabajo de cobertura, en lugar de una eliminación completa (práctica de la industria). Un trabajo de cobertura suele necesitar menos sesiones que la eliminación completa, pero ningún estudio ofrece un número fijo. Trabaja con tu tatuador: una vez que los contornos oscuros se han desvanecido a un gris suave, el artista suele poder diseñar encima sin que el trabajo anterior se transparente. Regla general del estudio: espera al menos de 8 a 12 semanas después de tu última sesión de láser, hasta que la piel se haya curado por completo, antes de tatuar.",
    "faq.q7_title": "¿Cómo influye mi fototipo de Fitzpatrick en la seguridad y la velocidad del tratamiento?",
    "faq.q7_body": "Los fototipos de Fitzpatrick I a III tienen menos melanina epidérmica, lo que generalmente da al especialista más margen sin afectar al color de la piel circundante. Los fototipos IV a VI contienen más melanina natural, que compite con el pigmento del tatuaje por la energía del láser y aumenta el riesgo de que la propia piel se oscurezca o se aclare (hiperpigmentación o hipopigmentación) si el enfoque no se adapta a ese fototipo. Un especialista con experiencia en pieles oscuras adaptará su enfoque en consecuencia; por eso mismo el plan de tratamiento se establece en persona, no por un sitio web.",
    "faq.q8_title": "¿Es dolorosa la eliminación de tatuajes con láser y qué opciones existen para aliviar el dolor?",
    "faq.q8_body": "La mayoría de las personas comparan el impacto del pulso láser con el chasquido de una banda elástica sobre la piel acompañado de calor intenso. Como las zonas tratadas suelen ser sensibles, las clínicas emplean diversos métodos para reducir las molestias: aire frío forzado continuo proyectado antes, durante y después de los disparos; cremas anestésicas tópicas aplicadas de 30 a 60 minutos antes; y compresión con hielo. En clínicas médicas pueden administrarse infiltraciones locales para zonas de alta sensibilidad.",
    "faq.q9_title": "¿Por qué las sesiones se espacian con semanas de diferencia y se pueden programar tratamientos antes?",
    "faq.q9_body": "Apresurar las sesiones no acelera la eliminación y aumenta el riesgo de daño en la piel. El láser divide la tinta en fragmentos más pequeños; luego tu cuerpo los elimina durante las semanas siguientes. El artículo de Kirby-Desai estimaba de 6 a 8 semanas entre sesiones, y un estudio a gran escala (Bencini et al., 2012) relacionó intervalos de 8 semanas o menos con un menor éxito, por lo que muchas clínicas ahora dejan espacios más largos. Tu clínica establece el intervalo.",
