    "results.dominant_colour": "Veelkleurige inkt ({pts} ptn): verschillende kleuren absorberen verschillende golflengten, dus er is vaak meer dan één laserinstelling nodig.",
    "results.dominant_density": "Aanzienlijk inktvolume ({pts} ptn): meer pigment betekent meestal meer sessies.",
    "results.dominant_scarring": "Littekenvorming of weefselverandering ({pts} ptn) maakt verwijdering langzamer en moeilijker.",
    "results.dominant_layering": "Gelaagd cover-up-werk ({pts} ptn): twee inktlagen, dus meer sessies.",
    "results.coverup_badge": "Voorbereidende schatting voor cover-up",
    "results.coverup_note": "Uw doel is vervaging voor een cover-up. Het getoonde sessiebereik is voor volledige verwijdering; een cover-up heeft er meestal minder nodig. Veel artiesten zoeken naar ongeveer 50–70% vervaging (praktijkregel). Geen enkele studie geeft een vaste fractie van sessies, dus uw kliniek en uw artiest bepalen samen wanneer het licht genoeg is.",
    "results.referral_badge": "Boven de drempel uit het onderzoek zelf",
    "results.referral_note": "De gepubliceerde Kirby-Desai-studie stelt dat een tatoeage boven de 15 punten moeilijk te verwijderen kan zijn en dat een arts moet beslissen of laser de juiste methode is. Uw score ligt boven die drempel: neem dit resultaat mee naar een persoonlijk consult bij een erkend laserspecialist of dermatoloog voordat u ervan uitgaat dat laserverwijdering de voor de hand liggende aanpak is.",
