    "calendar.ics_completed_alert": "Alle geplande behandelsessies zijn reeds geregistreerd als voltooid.",
    "limits.title": "Wat de Kirby-Desai-schaal niet kan bepalen",
    "limits.p1": "De Kirby-Desai-schaal biedt een statistisch referentiekader op basis van een retrospectieve studie met 100 patiënten. Het biedt geen individuele garantie. Vier klinische variabelen kunnen niet met een vragenlijst worden gemeten:",
    "limits.item_immune_title": "1. Individuele immuunrespons en lymfatische fagocytose",
    "limits.item_immune_desc": "De laser verpulvert inktpartikels; de macrofagen en het lymfestelsel van uw lichaam ruimen de inkt daadwerkelijk op. De activiteit van macrofagen en de metabolische opruimsnelheid verschillen sterk per persoon.",
    "limits.item_chemistry_title": "2. Ongereguleerde inktchemie en pigmentdiepte",
    "limits.item_chemistry_desc": "Tattoo-inkten zijn eigen mengsels van pigmenten, bindmiddelen en andere ingrediënten, en de diepte die de naald bereikte varieert. Beide veranderen hoe de inkt reageert op de laser.",
    "limits.item_smoking_title": "3. Roken en perifere microcirculatie",
    "limits.item_smoking_desc": "Uit één studie van 352 patiënten (Bencini et al., Arch Dermatol 2012) bleek dat rokers ongeveer 70% minder kans hadden om verwijdering te bereiken na 10 sessies dan niet-rokers. De auteurs suggereren dat sigarettenrook invloed kan hebben op de cellen die het pigment opruimen.",
    "limits.item_paradox_title": "4. Witte inkt en paradoxale verdonkering",
    "limits.item_paradox_desc": "Witte, huidkleurige en cosmetische inkten die titaandioxide of ijzeroxide bevatten, kunnen grijs of zwart worden wanneer ze gelaserd worden (paradoxale verdonkering), en die verdonkering kan moeilijk te verwijderen zijn.",
    "questions.title": "Vragen voor uw behandelend laserkliniek",
    "questions.subtitle": "Neem deze printbare controlelijst mee naar uw intakegesprek:",
    "questions.q1_title": "1. Proefbehandeling (Patch test)",
    "questions.q1_body": "Voert u eerst een kleine proefpuls uit op een onopvallende plek om mijn huidreactie te beoordelen en paradoxale verdonkering uit te sluiten alvorens de hele tatoeage te behandelen?",
    "questions.q2_title": "2. Rusttijd en behandelintervallen",
    "questions.q2_body": "Hoe bepaalt u de pauzes tussen sessies? Wordt het interval verlengd naarmate de inkt vervaagt, zodat mijn immuunsysteem voldoende tijd krijgt om de verbrijzelde pigmentdeeltjes af te voeren?",
    "questions.q3_title": "3. Pigmentkenmerken en bescherming van melanine",
    "questions.q3_body": "Welke lasergolflengten gebruikt u voor mijn specifieke kleuren, en hoe beschermt u het natuurlijke melanine in mijn huid tegen hypo- of hyperpigmentatie?",
    "questions.q4_title": "4. Stagnerende vervaging en behandelplan",
    "questions.q4_body": "Wat is uw klinisch protocol wanneer het vervagen stagneert of aanzienlijk trager verloopt na een aantal sessies?",
    "questions.q5_title": "5. Afstemming voor cover-up (indien van toepassing)",
    "questions.q5_body": "Als ik vervaag voor een cover-up, overlegt u dan zo nodig met mijn tatoeëerder om het ideale moment te bepalen waarop de tatoeage licht genoeg is voor het nieuwe ontwerp?",
