    "legal.disclaimer": "Klinische referentieverklaring: Deze schatter past het klinische Kirby-Desai scoringsalgoritme toe (Kirby W, Desai A, J Clin Aesthet Dermatol. 2009;2(3):32–37) voor informatieve en educatieve doeleinden. De werkelijke vervaging is afhankelijk van individuele lymfatische fagocytose, het type lasersysteem (nanoseconde vs picoseconde), de vaardigheid van de behandelaar, de spotgrootte en de inktchemie. Dit hulpmiddel vormt geen medisch advies en garandeert geen algehele verwijdering. Raadpleeg altijd een gediplomeerd laserarts of dermatoloog in een persoonlijke intake.",
