    "aftercare.title": "Nazorgchecklijst",
    "aftercare.subtitle": "Zorgvuldige nazorg verlaagt het risico op infectie en pigmentveranderingen. De instructies van uw eigen kliniek gaan voor.",
    "aftercare.stage1_title": "Fase 1: Acute genezing (Uur 0 tot 48)",
    "aftercare.stage1_item1": "Breng koude kompressen aan gedurende 10 tot 15 minuten per keer om zwelling te verminderen.",
    "aftercare.stage1_item2": "Leg een behandelde arm of een behandeld been hoger bij rusten om zwelling te helpen verminderen.",
    "aftercare.stage1_item3": "Breng een dun laagje vaseline of de zalf aan die u van uw kliniek krijgt; prik blaren niet door en zuig ze niet leeg.",
    "aftercare.stage1_item4": "Vermijd hete douches, sauna's, bubbelbaden en zware inspanning gedurende 48 uur.",
    "aftercare.stage2_title": "Fase 2: Herstel van de lederhuid (Dag 3 tot 14)",
    "aftercare.stage2_item1": "Reinig eenmaal daags voorzichtig met milde parfumvrije zeep; dep zachtjes droog.",
    "aftercare.stage2_item2": "Krab of peuter nooit aan korstjes of blaashuidjes om littekens en infecties te voorkomen.",
    "aftercare.stage2_item3": "Draag losse, ademende kleding over het gebied om mechanische wrijving te vermijden.",
    "aftercare.stage3_title": "Fase 3: Zonbescherming (Week 2 tot 8+)",
    "aftercare.stage3_item1": "Gebruik een brede-spectrum zonnebrandcrème (SPF 30 of hoger) of houd het gebied bedekt om het risico op pigmentveranderingen te verlagen.",
    "aftercare.stage3_item2": "Volg eventuele extra instructies van uw kliniek, zoals wanneer u weer mag zwemmen of sporten.",
    "aftercare.stage3_item3": "Houd de volledige tussenpoos aan die uw kliniek aanbeveelt vóór de volgende lasersessie.",
    "aftercare.progress_label": "Checklist voortgang: {done} van {total} afgevinkt",
    "trajectory.hover_prompt": "Beweeg de muis over, tik op of gebruik de pijltjestoetsen op de punten langs de curve om de verwachte mijlpalen en tijdlijn te bekijken.",
