    "trajectory.score_note": "Kirby-Desai-score: {score} ptn | Richtbereik: {min} tot {max} sessies",
    "faq.title": "Veelgestelde klinische vragen",
    "faq.subtitle": "Antwoorden over hoe laserverwijdering werkt, voorbereiding en plateaus. Het advies van uw kliniek gaat voor.",
    "faq.expand_all": "Alles uitklappen",
    "faq.collapse_all": "Alles inklappen",
    "faq.direct_link": "Directe link naar deze vraag",
    "faq.link_copied": "Directe link gekopieerd naar klembord",
    "faq.q1_title": "Wat gebeurt er als de laserbehandeling niet meer lijkt te werken of een plateau bereikt?",
    "faq.q1_body": "Een vervagingsplateau treedt vaak op wanneer de inkt die gemakkelijk uiteenvalt is opgeruimd, waardoor dieper of hardnekkiger pigment achterblijft. Wanneer de vervaging stagneert, kan uw behandelaar de aanpak veranderen voor wat er overblijft, of langere tussenpozen aanhouden tussen sessies (vaak 12 weken of meer, een gebruikelijke praktijk in klinieken) om het lichaam meer tijd te geven om de fragmenten op te ruimen. Wat er eventueel verandert, is een beslissing die uw behandelaar persoonlijk neemt, niet iets dat deze tool kan specificeren.",
    "faq.q2_title": "Hoe moet ik mijn huid voorbereiden op een laserbehandeling?",
    "faq.q2_body": "Klinieken vragen u doorgaans om blootstelling aan de zon, zonnebanken en zelfbruiners te vermijden gedurende enkele weken vóór de behandeling (vaak 4 weken of meer; volg de eigen regel van uw kliniek), omdat een gebruinde huid met de inkt concurreert om laserenergie en het risico op pigmentveranderingen vergroot. Velen vragen u ook om het gebied de dag tevoren te scheren, aan te komen met een schone huid zonder cosmetica, vochtinbrengende crèmes of deodorant, en verdovende crème alleen te gebruiken als zij dat zeggen. Sommigen vragen u om alcohol en aspirine vooraf te vermijden. Dit zijn praktijken in klinieken: de instructies van uw behandelaar gaan voor.",
    "faq.q3_title": "Waarom vereisen meerkleurige inkten (groen, blauw, geel) andere lasers dan zwart?",
    "faq.q3_body": "Laserverwijdering werkt doordat een pigment lichtenergie absorbeert en uiteenvalt in deeltjes die het lichaam kan afvoeren; een bepaalde golflengte werkt alleen goed als het doelpigment die daadwerkelijk absorbeert. Zwarte inkt absorbeert een zeer breed lichtspectrum en reageert doorgaans het meest betrouwbaar. Rode, blauwe, groene en paarse pigmenten absorberen smaller, en geel staat erom bekend de moeilijkste kleur te zijn omdat het licht slecht absorbeert binnen het voor de huid veilige bereik. Precies daarom heeft meerkleurig werk vaak meer sessies nodig dan effen zwart. Welke laser en golflengte uw behandelaar voor uw specifieke kleuren kiest, is een klinische beslissing die persoonlijk wordt genomen, niet door deze tool.",
    "faq.q4_title": "Kan witte inkt of cosmetisch tatoeagepigment zwart worden door laserstraling?",
    "faq.q4_body": "Ja. Dit wordt paradoxale verdonkering genoemd. Witte, huidkleurige en veel cosmetische pigmenten bevatten titaandioxide of ijzeroxide. De laserpuls kan deze pigmenten chemisch veranderen, zodat witte, roze of huidkleurige inkt grijs of zwart wordt, en die verdonkering kan moeilijk te verwijderen zijn. Dit is waarom behandelaars een klein plekje op cosmetische of witte inkt testen voordat ze het hele gebied behandelen.",
    "faq.q5_title": "Hoeveel invloed heeft roken op het aantal benodigde behandelingen?",
    "faq.q5_body": "Uit één studie van 352 patiënten in Milaan (Bencini et al., Archives of Dermatology, 2012) bleek dat rokers ongeveer 70% minder kans hadden om verwijdering te bereiken na 10 sessies dan niet-rokers. De auteurs suggereren dat stoffen in sigarettenrook invloed kunnen hebben op de cellen die het afgebroken pigment opruimen. Het is één studie, en het mat de kans op succes, niet een aantal extra sessies, dus deze tool voegt geen rookpercentage toe aan uw schatting.",
    "faq.q6_title": "Wanneer is een tatoeage voldoende vervaagd voor een cover-up in plaats van volledige verwijdering?",
    "faq.q6_body": "Veel tatoeëerders zoeken naar grofweg 50% tot 70% vervaging voorafgaand aan een cover-up, in plaats van volledige verwijdering (industriepraktijk). Een cover-up heeft meestal minder sessies nodig dan volledige verwijdering, maar geen enkel onderzoek geeft een vast aantal. Werk samen met uw tatoeëerder: zodra donkere contouren zijn vervaagd tot een zacht grijs, kan de artiest er meestal overheen ontwerpen zonder dat het oude werk erdoorheen schijnt. Studio-vuistregel: wacht ten minste 8 tot 12 weken na uw laatste lasersessie, totdat de huid volledig is genezen, voordat u gaat tatoeëren.",
    "faq.q7_title": "Hoe beïnvloedt mijn Fitzpatrick-huidtype de veiligheid en de behandelduur?",
    "faq.q7_body": "Fitzpatrick-huidtypen I tot III hebben minder epidermaal melanine, wat de behandelaar doorgaans meer ruimte geeft zonder de omliggende huidskleur te beïnvloeden. Huidtypen IV tot VI bevatten meer natuurlijk melanine, dat concurreert met het tatoeagepigment om de laserenergie en het risico verhoogt dat de huid zelf donkerder of lichter wordt (hyperpigmentatie of hypopigmentatie) als de aanpak niet wordt afgestemd op dat huidtype. Een behandelaar met ervaring in donkere huidtypen past zijn aanpak daarop aan; precies daarom wordt het behandelplan persoonlijk vastgesteld, niet door een website.",
    "faq.q8_title": "Is laser-tatoeageverwijdering pijnlijk en welke vormen van pijnstilling zijn er?",
    "faq.q8_body": "De meeste mensen vergelijken het gevoel van een laserpuls met het elastiekje dat tegen de huid schiet, gepaard met een felle hitteprikkel. Omdat behandelde zones gevoelig kunnen zijn, hanteren klinieken verschillende maatregelen om het comfort te verhogen: continue geforceerde koude lucht gericht op de huid voor, tijdens en na de pulsen; verdovende crèmes die 30 tot 60 minuten vooraf worden aangebracht; en ijskompressen. In medische praktijken kunnen voor zeer gevoelige lichaamslocaties ook lokale infiltraties worden overwogen.",
    "faq.q9_title": "Waarom worden sessies weken uit elkaar gepland, en kunnen behandelingen eerder worden ingepland?",
    "faq.q9_body": "Het overhaasten van sessies versnelt de verwijdering niet en verhoogt het risico op huidschade. De laser breekt de inkt af in kleinere fragmenten; uw lichaam ruimt deze vervolgens in de daaropvolgende weken op. Het Kirby-Desai-artikel ging uit van 6 tot 8 weken tussen sessies, en één grootschalige studie (Bencini et al., 2012) koppelde tussenpozen van 8 weken of minder aan minder succes, dus veel klinieken laten tegenwoordig langere tussenpozen. Uw kliniek stelt het interval in.",
