    "results.coverup_badge": "Estimativa de preparação para cover-up",
    "results.coverup_note": "O seu objetivo é o desbotamento para uma cobertura. O intervalo de sessões apresentado é para remoção total; uma cobertura precisa habitualmente de menos. Muitos artistas procuram cerca de 50–70% de desbotamento (prática da indústria). Nenhum estudo indica uma fração fixa de sessões, pelo que a sua clínica e o seu tatuador decidem em conjunto quando está suficientemente claro.",
