    "results.referral_note": "O estudo publicado de Kirby-Desai afirma que, acima de 15 pontos, uma tatuagem pode ser difícil de remover e que deve ser um médico a decidir se o laser é o método certo. A sua pontuação está acima desse limiar: leve este resultado a uma consulta presencial com um especialista em laser ou dermatologista licenciado antes de assumir que a remoção a laser é a abordagem evidente.",
