    "calendar.ics_completed_alert": "Todas as sessões planeadas já se encontram registadas como concluídas.",
    "limits.title": "O que a escala Kirby-Desai não pode prever",
    "limits.p1": "A escala Kirby-Desai fornece uma estimativa estatística de referência obtida num estudo retrospectivo de 100 pacientes. Não constitui uma garantia individual. Quatro fatores clínicos não podem ser mensurados através de um questionário:",
    "limits.item_immune_title": "1. Resposta imunológica e fagocitose linfática individual",
    "limits.item_immune_desc": "O laser fragmenta as partículas de tinta; são os macrófagos e o sistema linfático do organismo que procedem à sua eliminação. A eficiência macrofágica varia consideravelmente entre indivíduos.",
    "limits.item_chemistry_title": "2. Composição química das tintas e profundidade do depósito",
    "limits.item_chemistry_desc": "As tintas de tatuagem são misturas proprietárias de pigmentos, aglutinantes e outros ingredientes, e a profundidade alcançada pela agulha varia. Ambos alteram a forma como a tinta reage ao laser.",
    "limits.item_smoking_title": "3. Tabagismo e microcirculação periférica",
    "limits.item_smoking_desc": "Um estudo de 352 pacientes (Bencini et al., Arch Dermatol 2012) concluiu que os fumadores tinham cerca de 70% menos probabilidade do que os não fumadores de alcançar a remoção após 10 sessões. Os autores sugerem que o fumo do cigarro pode afetar as células que eliminam o pigmento.",
    "limits.item_paradox_title": "4. Tinta branca e escurecimento paradoxal",
    "limits.item_paradox_desc": "Tintas brancas, cor da pele e cosméticas que contêm dióxido de titânio ou óxido de ferro podem ficar cinzentas ou pretas quando expostas ao laser (escurecimento paradoxal), e esse escurecimento pode ser difícil de remover.",
    "questions.title": "Questões essenciais para a sua clínica de laser",
    "questions.subtitle": "Leve esta lista de consulta impressa para a sua primeira consulta de avaliação:",
    "questions.q1_title": "1. Disparo de teste preliminar (Patch test)",
    "questions.q1_body": "Irá realizar um teste prévio numa pequena área discreta para avaliar a resposta biológica da pele e descartar escurecimento paradoxal antes do tratamento integral?",
    "questions.q2_title": "2. Espaçamento e intervalos entre sessões",
    "questions.q2_body": "Como é determinado o tempo de descanso entre sessões? O intervalo será alargado à medida que a tinta clareia, dando tempo ao sistema imunitário para drenar os pigmentos fragmentados?",
    "questions.q3_title": "3. Comprimentos de onda e proteção da melanina",
    "questions.q3_body": "Quais os comprimentos de onda de laser específicos para as minhas cores, e que precauções são adotadas para evitar alterações pigmentares na melanina natural da minha pele?",
    "questions.q4_title": "4. Estagnação do clareamento e protocolo",
    "questions.q4_body": "Qual é o protocolo clínico caso o clareamento estagne ou desacelere visivelmente após várias sessões?",
    "questions.q5_title": "5. Coordenação para cover-up (se aplicável)",
    "questions.q5_body": "Se o meu objetivo for clarear para um cover-up, articulam a evolução com o meu tatuador para definir o momento exato em que a pele está pronta para a nova tatuagem?",
