    "legal.disclaimer": "Aviso de referência clínica: Este estimador aplica o algoritmo de pontuação clínica Kirby-Desai (Kirby W, Desai A, J Clin Aesthet Dermatol. 2009;2(3):32–37) para fins puramente informativos e educativos. A remoção real varia em função da fagocitose linfática individual, tecnologia laser (nanossegundos vs picossegundos), experiência do operador, diâmetro do feixe e química da tinta. Esta ferramenta não constitui aconselhamento médico nem garante a remoção total. Consulte sempre pessoalmente um médico dermatologista ou especialista certificado em laser.",
