    "aftercare.title": "Lista de Verificação de Cuidados Posteriores",
    "aftercare.subtitle": "Cuidados posteriores atentos reduzem o risco de infeção e alterações de pigmentação. As instruções da sua clínica têm prioridade.",
    "aftercare.stage1_title": "Fase 1: Cicatrização aguda (Horas 0 a 48)",
    "aftercare.stage1_item1": "Aplique compressas frias durante 10 a 15 minutos de cada vez para reduzir o inchaço.",
    "aftercare.stage1_item2": "Eleve o braço ou a perna tratada ao descansar para ajudar a reduzir o inchaço.",
    "aftercare.stage1_item3": "Aplique uma camada fina de vaselina ou da pomada fornecida pela sua clínica; não rebente nem esvazie as bolhas.",
    "aftercare.stage1_item4": "Evite banhos muito quentes, saunas, imersão em água quente e suor intenso durante 48 horas.",
    "aftercare.stage2_title": "Fase 2: Recuperação dérmica (Dias 3 a 14)",
    "aftercare.stage2_item1": "Limpe suavemente uma vez ao dia com sabonete neutro sem perfume; seque com toques suaves.",
    "aftercare.stage2_item2": "Nunca puxe, coce ou remova crostas ou a pele das bolhas para evitar cicatrizes e infeções.",
    "aftercare.stage2_item3": "Vista roupas largas e respiráveis para evitar o atrito mecânico constante sobre a pele.",
    "aftercare.stage3_title": "Etapa 3: Proteção Solar (Semanas 2 a 8+)",
    "aftercare.stage3_item1": "Utilize um protetor solar de largo espetro (SPF 30 ou superior) ou mantenha a área coberta para reduzir o risco de alterações de pigmentação.",
    "aftercare.stage3_item2": "Siga quaisquer instruções adicionais da sua clínica, tais como quando pode voltar a nadar ou fazer exercício.",
    "aftercare.stage3_item3": "Permita o intervalo completo recomendado pela sua clínica antes da sessão a laser seguinte.",
    "aftercare.progress_label": "Progresso da lista: {done} de {total} concluídos",
