    "trajectory.score_note": "Pontuação Kirby-Desai: {score} pts | Intervalo estimado: {min} a {max} sessões",
    "faq.title": "Perguntas clínicas frequentes",
    "faq.subtitle": "Respostas sobre como funciona a remoção a laser, preparação e estabilização. O conselho da sua clínica tem prioridade.",
    "faq.expand_all": "Expandir tudo",
    "faq.collapse_all": "Recolher tudo",
    "faq.direct_link": "Link direto para esta pergunta",
    "faq.link_copied": "Link direto copiado para a área de transferência",
    "faq.q1_title": "O que acontece se a remoção a laser parar de funcionar ou atingir um platô de clareamento?",
    "faq.q1_body": "Uma estagnação no desbotamento ocorre frequentemente quando a tinta que se decompõe facilmente foi eliminada, deixando para trás um pigmento mais profundo ou persistente. Quando o desbotamento estagna, o seu profissional pode alterar a abordagem para o que resta, ou deixar intervalos mais longos entre as sessões (frequentemente 12 semanas ou mais, uma prática comum nas clínicas) para dar ao corpo mais tempo para eliminar os fragmentos. O que muda, caso algo mude, é uma decisão tomada pessoalmente pelo seu profissional, e não algo que esta ferramenta possa especificar.",
    "faq.q2_title": "Como devo preparar minha pele antes de uma sessão de remoção a laser?",
    "faq.q2_body": "As clínicas pedem habitualmente para evitar a exposição solar, solários e autobronzeadores durante várias semanas antes do tratamento (frequentemente 4 semanas ou mais; siga a regra da sua clínica), porque a pele bronzeada compete com a tinta pela energia do laser e aumenta o risco de alterações de pigmentação. Muitas também pedem para barbear a área no dia anterior, comparecer com a pele limpa e sem cosméticos, hidratantes ou desodorizante, e usar creme anestésico apenas se lhe for indicado. Algumas pedem para evitar álcool e aspirina antes. Estas são práticas clínicas: as instruções do seu profissional têm prioridade.",
    "faq.q3_title": "Por que tintas coloridas (verde, azul, amarelo) exigem lasers diferentes do preto?",
    "faq.q3_body": "A remoção a laser funciona porque um pigmento absorve energia luminosa e se fragmenta em partículas que o corpo consegue eliminar; um determinado comprimento de onda só é eficaz se o pigmento-alvo o absorver de facto. A tinta preta absorve uma gama muito ampla de luz e geralmente responde de forma mais fiável. Os pigmentos vermelho, azul, verde e violeta absorvem de forma mais restrita, e o amarelo é notoriamente a cor mais difícil de eliminar por absorver mal a luz dentro do intervalo seguro para a pele. É exatamente por isso que um trabalho multicolorido costuma exigir mais sessões do que um preto sólido. A escolha do laser e do comprimento de onda para as suas cores específicas é uma decisão clínica tomada pessoalmente pelo seu profissional, não por esta ferramenta.",
    "faq.q4_title": "A tinta branca ou pigmentos de maquiagem definitiva podem escurecer com o laser?",
    "faq.q4_body": "Sim. Isto chama-se escurecimento paradoxal. Os pigmentos brancos, cor da pele e muitos cosméticos contêm dióxido de titânio ou óxido de ferro. O impulso do laser pode alterar quimicamente estes pigmentos, fazendo com que a tinta branca, rosa ou cor da pele fique cinzenta ou preta, e esse escurecimento pode ser difícil de remover. É por isso que os profissionais testam um pequeno ponto em tinta cosmética ou branca antes de tratar toda a área.",
    "faq.q5_title": "O quanto o tabagismo influencia na quantidade de sessões necessárias?",
    "faq.q5_body": "Um estudo de 352 pacientes em Milão (Bencini et al., Archives of Dermatology, 2012) concluiu que os fumadores tinham cerca de 70% menos probabilidade do que os não fumadores de alcançar a remoção após 10 sessões. Os autores sugerem que as substâncias presentes no fumo do cigarro podem afetar as células que eliminam o pigmento decomposto. É um único estudo, e mediu a probabilidade de sucesso e não um número de sessões extra, pelo que esta ferramenta não adiciona uma percentagem de tabagismo à sua estimativa.",
    "faq.q6_title": "Quando uma tatuagem está clara o suficiente para uma cobertura em vez de remoção total?",
    "faq.q6_body": "Muitos tatuadores procuram aproximadamente 50% a 70% de desbotamento antes de uma cobertura, em vez da remoção total (prática da indústria). Uma cobertura precisa habitualmente de menos sessões do que a remoção total, mas nenhum estudo indica um número fixo. Trabalhe com o seu tatuador: assim que os contornos escuros tenham desbotado para um cinzento suave, o artista consegue habitualmente desenhar por cima sem que o trabalho antigo transpareça. Regra prática de estúdio: espere pelo menos 8 a 12 semanas após a sua última sessão a laser, até que a pele esteja totalmente sarada, antes de se tatuar.",
    "faq.q7_title": "Como meu fototipo de Fitzpatrick influencia a segurança e o tempo do tratamento?",
    "faq.q7_body": "Os fototipos de Fitzpatrick I a III têm menos melanina epidérmica, o que geralmente dá ao profissional mais margem sem afetar a cor da pele circundante. Os fototipos IV a VI contêm mais melanina natural, que compete com o pigmento da tatuagem pela energia do laser e aumenta o risco de a própria pele escurecer ou clarear (hiperpigmentação ou hipopigmentação) caso a abordagem não seja ajustada a esse fototipo. Um profissional experiente com peles mais escuras ajustará a sua abordagem em conformidade; é exatamente por isso que o plano de tratamento é definido pessoalmente, não por um site.",
    "faq.q8_title": "A remoção de tatuagens a laser é dolorosa e quais são as opções de alívio da dor?",
    "faq.q8_body": "A maioria das pessoas compara a sensação do disparo do laser ao estalo de um elástico na pele associado a calor intenso. Como as áreas tratadas costumam ser sensíveis, as clínicas adotam diversas estratégias para minimizar o desconforto: ar frio contínuo direcionado sobre a pele antes, durante e após os disparos; cremes anestésicos tópicos aplicados 30 a 60 minutos antes da sessão; e compressas de gelo. Em ambiente médico, infiltrações anestésicas locais podem ser realizadas em regiões anatômicas de maior sensibilidade.",
    "faq.q9_title": "Porque é que as sessões são espaçadas por semanas, e os tratamentos podem ser agendados mais cedo?",
    "faq.q9_body": "Apressar as sessões não acelera a remoção e aumenta o risco de danos na pele. O laser fragmenta a tinta em pedaços mais pequenos; o seu corpo elimina-os de seguida ao longo das semanas seguintes. O artigo de Kirby-Desai assumia 6 a 8 semanas entre sessões, e um grande estudo (Bencini et al., 2012) associou intervalos de 8 semanas ou menos a um menor sucesso, pelo que muitas clínicas deixam agora intervalos mais longos. A sua clínica define o intervalo.",
