    "limits.title": "สิ่งที่มาตราวัด Kirby-Desai ไม่สามารถทราบได้",
    "limits.p1": "มาตราวัด Kirby-Desai ให้ช่วงอ้างอิงทางสถิติจากการศึกษาย้อนหลังในผู้ป่วย 100 ราย ไม่ใช่การรับประกันสำหรับบุคคล ตัวแปรทางคลินิกสี่ประการไม่สามารถวัดได้ด้วยแบบสอบถาม:",
    "limits.item_immune_title": "1. การกลืนกินของภูมิคุ้มกันและระบบน้ำเหลืองของแต่ละบุคคล",
    "limits.item_immune_desc": "เลเซอร์ทำให้อนุภาคหมึกแตกละเอียด ส่วนที่ร่างกายกำจัดหมึกออกจริงคือแมคโครฟาจและระบบน้ำเหลือง กิจกรรมของแมคโครฟาจและความเร็วในการกำจัดทางเมแทบอลิซึมของแต่ละบุคคลแตกต่างกันมาก",
    "limits.item_chemistry_title": "2. เคมีของหมึกที่ไม่ได้มาตรฐานและความลึกของเม็ดสี",
    "limits.item_chemistry_desc": "หมึกสักคือส่วนผสมที่เป็นกรรมสิทธิ์ของเม็ดสี สารยึดเกาะ และส่วนผสมอื่นๆ รวมถึงความลึกที่เข็มเข้าถึงจะแตกต่างกัน ทั้งสองอย่างนี้เปลี่ยนวิธีที่หมึกตอบสนองต่อเลเซอร์",
    "limits.item_smoking_title": "3. การสูบบุหรี่และการไหลเวียนระดับจุลภาค",
    "limits.item_smoking_desc": "การศึกษาผู้ป่วย 352 ราย (Bencini et al., Arch Dermatol 2012) พบว่าผู้สูบบุหรี่มีโอกาสน้อยกว่าผู้ไม่สูบบุหรี่ประมาณ 70% ที่จะลบออกได้หมดหลังจากผ่านไป 10 ครั้ง ผู้เขียนแนะนำว่าควันบุหรี่อาจส่งผลต่อเซลล์ที่ทำหน้าที่ขับเม็ดสีออก",
    "limits.item_paradox_title": "4. หมึกสีขาวและการคล้ำขึ้นแบบขัดแย้ง",
    "limits.item_paradox_desc": "หมึกสีขาว สีเนื้อ และสีเครื่องสำอางที่มีไทเทเนียมไดออกไซด์หรือไอรอนออกไซด์ สามารถเปลี่ยนเป็นสีเทาหรือสีดำได้เมื่อถูกเลเซอร์ (ความหมองคล้ำย้อนกลับ) และความหมองคล้ำนั้นอาจลบออกได้ยาก",
    "questions.title": "คำถามสำหรับคลินิกเลเซอร์ของคุณ",
    "questions.subtitle": "นำรายการตรวจสอบที่พิมพ์ได้นี้ไปด้วยในการปรึกษาครั้งแรก:",
    "questions.q1_title": "1. การทดสอบแผ่นแปะ",
    "questions.q1_body": "คุณจะทดสอบจุดเล็ก ๆ ในบริเวณที่ไม่เด่นชัดก่อนหรือไม่ เพื่อประเมินปฏิกิริยาของผิวฉันและตรวจหาการคล้ำขึ้นของเม็ดสีแบบขัดแย้ง ก่อนที่จะรักษารอยสักทั้งหมด",
    "questions.q2_title": "2. ระยะห่างและช่วงเวลาระหว่างครั้ง",
    "questions.q2_body": "คุณกำหนดระยะห่างระหว่างการรักษาอย่างไร เมื่อหมึกจางลง จะขยายช่วงเวลาออกไปเพื่อให้ระบบภูมิคุ้มกันของฉันมีเวลาเพียงพอในการกำจัดเม็ดสีที่แตกตัวแล้วหรือไม่",
    "questions.q3_title": "3. รายละเอียดของเม็ดสีและการปกป้องเมลานินตามธรรมชาติ",
    "questions.q3_body": "คุณจะใช้ความยาวคลื่นเลเซอร์ใดกับสีหมึกเฉพาะของฉัน และคุณมีมาตรการป้องกันอะไรบ้างเพื่อปกป้องเมลานินตามธรรมชาติของผิวฉันจากภาวะเม็ดสีจางหรือเม็ดสีเข้มขึ้น",
    "questions.q4_title": "4. ระดับการจางที่หยุดนิ่งและการเปลี่ยนแปลงการรักษา",
    "questions.q4_body": "โปรโตคอลทางคลินิกของคุณคืออะไร หากรอยสักเข้าสู่ระดับการจางที่หยุดนิ่งหรือไม่ดีขึ้นหลังจากทำไปหลายครั้ง",
    "questions.q5_title": "5. การทำงานร่วมกับการปกปิดรอยสัก (หากเกี่ยวข้อง)",
    "questions.q5_body": "หากการจางเพื่อปกปิดรอยสัก คุณจะประเมินรอยสักร่วมกับศิลปินสักของฉัน เพื่อระบุจุดที่แน่ชัดว่าการจางเพียงพอต่อการสักผลงานใหม่แล้วหรือไม่",
