    "aftercare.stage1_title": "ระยะที่ 1: การฟื้นตัวเฉียบพลัน (ชั่วโมงที่ 0 ถึง 48)",
    "aftercare.stage1_item1": "ประคบเย็นครั้งละ 10 ถึง 15 นาที เพื่อลดอาการบวม",
    "aftercare.stage1_item2": "ยกแขนหรือขาที่ได้รับการรักษาขึ้นเมื่อพักผ่อนเพื่อช่วยลดอาการบวม",
