    "aftercare.stage1_item4": "หลีกเลี่ยงการอาบน้ำร้อน ซาวน่า อ่างน้ำวน และการเหงื่อออกมากเป็นเวลา 48 ชั่วโมง",
    "aftercare.stage2_title": "ระยะที่ 2: การฟื้นตัวของชั้นหนังแท้ (วันที่ 3 ถึง 14)",
    "aftercare.stage2_item1": "ทำความสะอาดอย่างเบามือวันละครั้งด้วยสบู่อ่อนที่ไม่มีน้ำหอม และซับให้แห้งด้วยกระดาษเช็ดมือที่สะอาด",
    "aftercare.stage2_item2": "ห้ามแกะ เกา หรือลอกสะเก็ดแห้งหรือเปลือกตุ่มพอง เพื่อป้องกันแผลเป็นและการติดเชื้อ",
    "aftercare.stage2_item3": "สวมเสื้อผ้าหลวม นุ่ม และระบายอากาศได้ดีคลุมบริเวณนั้น เพื่อหลีกเลี่ยงการเสียดสีทางกล",
    "aftercare.stage3_title": "ขั้นตอนที่ 3: การป้องกันแสงแดด (สัปดาห์ที่ 2 ถึง 8+)",
